/* Native study content — curated from administrator-provided materials. */
window.PREP_DEVICE_LESSONS = {"version":1,"title":"Device Configuration and Management","chapters":[{"id":1,"title":"Instalare și configurare Windows","english":"Windows Installation and Configuration"},{"id":2,"title":"Aplicații și periferice","english":"Windows Feature, Application and Peripheral Management"},{"id":3,"title":"Date și stocare","english":"Data Access and Management"},{"id":4,"title":"Securitatea dispozitivelor","english":"Device Security"},{"id":5,"title":"Administrare și depanare","english":"Windows Management and Troubleshooting"}],"lessons":[{"id":"1.1","chapter":1,"title":"Componentele calculatorului","subtitle":"Recunoaște piesa, explică rolul și verifică compatibilitatea.","sections":[{"title":"Imaginea de ansamblu","text":"CPU execută instrucțiuni, RAM păstrează datele active, stocarea păstrează fișierele, GPU procesează grafica, iar placa de bază le conectează. Performanța depinde de întregul sistem, nu de o singură piesă.","table":{"headers":["Componentă","Rol","Indiciu de memorare"],"rows":[["CPU / APU","Instrucțiuni și calcule / CPU + GPU integrat","Prelucrează"],["RAM","Date active, volatile","Lucrează acum"],["SSD / HDD","Date nevolatile","Păstrează"],["GPU","Grafică și calcule paralele","Desenează"],["Motherboard","Conexiuni și compatibilitate","Leagă"]]}},{"title":"Placa de bază (Motherboard)","text":"Socket-ul trebuie să fie compatibil cu procesorul; uneori este necesară și o versiune BIOS/UEFI potrivită. Sloturile DIMM acceptă generația RAM specificată. PCIe conectează GPU și alte plăci, SATA conectează unități SATA, iar M.2 este un format de conector/modul care poate suporta SATA sau PCIe, după model.","bullets":["Chipset-ul gestionează o parte din conectivitate; în sistemele moderne, controlerul de memorie este de regulă în CPU.","ATX, microATX și Mini-ITX diferă ca dimensiune și posibilități de extindere. Verifică și carcasa.","Liniile PCIe și porturile pot fi partajate. Consultă manualul înainte de extindere.","Ieșirile video ale plăcii de bază necesită suport grafic corespunzător în configurație."],"image":"motherboard"},{"title":"RAM: memoria de lucru","text":"RAM este volatilă: conținutul se pierde fără alimentare. Mai multă RAM ajută când aplicațiile depășesc memoria disponibilă; nu face automat CPU-ul mai rapid. DDR înseamnă Double Data Rate: transfer pe ambele fronturi ale semnalului de ceas.","bullets":["DDR3, DDR4 și DDR5 nu sunt interschimbabile. Verifică generația, formatul DIMM/SO-DIMM și capacitatea acceptată.","MT/s exprimă rata transferurilor; nu confunda direct MT/s cu MHz.","Dual channel folosește canale de memorie în paralel; montarea corectă depinde de manualul plăcii."],"image":"ram"},{"title":"CPU, APU și arhitecturi","text":"x86 desemnează familia de instrucțiuni; în cerințele software, x86 înseamnă adesea versiunea pe 32 de biți, iar x64 extensia pe 64 de biți. ARM și ARM64 sunt alte arhitecturi. Sistemul de operare, aplicația și driverele trebuie să fie compatibile.","table":{"headers":["Termen","De reținut"],"rows":[["32 de biți","Spațiul de adrese de 32 de biți este de 4 GiB; limitele RAM depind și de sistem."],["x64","Adresează mai multă memorie; multe aplicații x86 rulează prin compatibilitate. Driverele trebuie să corespundă."],["ARM64","Folosit pe telefoane, PC-uri și servere; emularea aplicațiilor depinde de platformă."],["APU","Denumire folosită mai ales de AMD pentru CPU cu GPU integrat; nu garantează grafică comutabilă."]]},"image":"cpu"},{"title":"GPU integrat versus dedicat","text":"GPU este procesorul grafic; placa video este ansamblul care poate include GPU, VRAM și răcire. Grafica integrată utilizează de regulă RAM partajată. O placă dedicată are de regulă VRAM proprie și se conectează prin PCIe x16. Performanța și consumul diferă mult între modele.","bullets":["Utilizări: afișaj, accelerare 2D/3D, montaj video și calcule paralele.","AMD, NVIDIA și Intel produc GPU-uri. RTX și DLSS sunt tehnologii NVIDIA, nu funcții universale.","Într-un laptop hibrid, sistemul poate alege GPU-ul în funcție de aplicație și politica de alimentare."],"image":"gpu"},{"title":"Stocare: HDD, SSD SATA, SSD NVMe","text":"HDD folosește platane magnetice și piese mobile. SSD folosește memorie flash și are latență mai mică. SATA este o interfață; NVMe este un protocol folosit de SSD-uri prin PCIe. M.2 nu înseamnă automat NVMe.","table":{"headers":["Tip","Punct forte","Limitare"],"rows":[["HDD","Cost/GB adesea mai mic","Mai lent la acces aleatoriu; sensibil la șocuri"],["SSD SATA","Pornire și aplicații rapide","Limitat de interfața SATA"],["SSD NVMe","Latență mică și debit ridicat","Necesită compatibilitate PCIe/NVMe și răcire potrivită"]]},"bullets":["Durata de viață nu este un număr fix de ani. Pentru SSD verifică TBW și garanția.","Orice unitate poate ceda: păstrează backup separat."],"image":"storage"}],"cards":[{"front":"RAM sau SSD: ce se pierde la oprire?","back":"Conținutul RAM. SSD-ul este nevolatil."},{"front":"M.2 înseamnă NVMe?","back":"Nu. M.2 este format; modulul și slotul pot utiliza SATA sau PCIe/NVMe."},{"front":"Ce integrează un APU?","back":"CPU și GPU pe același cip/ansamblu, în terminologia producătorului."},{"front":"Ce verifici înainte de montarea RAM?","back":"Generația DDR, formatul, capacitatea și compatibilitatea plăcii/CPU."},{"front":"Windows x64 rulează nativ aplicații Windows pe 16 biți?","back":"Nu. Compatibilitatea cu multe aplicații pe 32 de biți nu înseamnă suport nativ pentru cele pe 16 biți."}],"quiz":[{"prompt":"Unde se află temporar datele aplicațiilor active?","options":["Doar în BIOS","În RAM","În cablul HDMI"],"answer":1,"why":"RAM este memoria de lucru volatilă."},{"prompt":"Ai un SSD M.2 SATA și un slot numai PCIe/NVMe. Este suficient formatul fizic?","options":["Da, toate M.2 sunt identice","Da, dacă este de 1 TB","Nu, protocolul trebuie să fie compatibil"],"answer":2,"why":"Formatul M.2 nu garantează compatibilitatea SATA/NVMe."},{"prompt":"Ce piesă execută instrucțiunile generale ale aplicațiilor?","options":["HDD","CPU","Portul USB"],"answer":1,"why":"CPU interpretează și execută instrucțiuni."},{"prompt":"Ce justifică de obicei o placă grafică dedicată?","options":["Stocarea permanentă a documentelor","Înlocuirea plăcii de bază","Randare 3D intensivă"],"answer":2,"why":"GPU-ul dedicat poate oferi putere grafică și VRAM proprie."}],"warning":null,"videos":[],"source":"Materialele de curs furnizate de administrator: obiectivul 1.1. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Componentele calculatorului","url":"https://learn.microsoft.com/search/?terms=computer%20hardware"}],"minutes":7},{"id":"1.2","chapter":1,"title":"Active Directory și politici","subtitle":"Identități, resurse și administrare centralizată.","sections":[{"title":"Ce face Active Directory Domain Services?","text":"AD DS este serviciul de director pentru domenii Windows: păstrează obiecte precum utilizatori, grupuri și computere, susține autentificarea și ajută la administrarea accesului. Controlerele de domeniu (Domain Controllers, DC) găzduiesc serviciul și replică datele directorului.","image":"ad"},{"title":"Cont de domeniu versus administrator","text":"Un cont de domeniu reprezintă identitatea administrată în AD. Drepturile lui provin din grupuri, politici și permisiuni; faptul că este cont de domeniu nu îl face administrator. Domain Admins este un grup foarte privilegiat; pentru sarcini limitate se preferă delegarea și conturi administrative separate.","table":{"headers":["Identitate / rol","Scop"],"rows":[["Domain user","Autentificare și acces la resursele autorizate"],["Local administrator","Administrarea unui anumit computer"],["Domain administrator","Administrarea domeniului, cu privilegii extinse"]]}},{"title":"Domeniu, arbore, pădure și OU","text":"Un domeniu grupează obiecte într-un spațiu de administrare și autentificare. Un arbore reunește domenii cu spațiu de nume DNS contiguu. O pădure (forest) cuprinde unul sau mai multe domenii care împart schema și configurația; pădurea este limita principală de securitate AD. OU (Organizational Unit) organizează obiectele, permite delegarea și asocierea GPO.","image":"ad-tree"},{"title":"Administrare centralizată","text":"Administratorul creează utilizatori, îi adaugă în grupuri și atribuie acces grupurilor, în loc să gestioneze separat fiecare persoană. GPO (Group Policy Object) poate configura securitatea și mediul Windows pentru utilizatori și computere. Politicile locale se aplică pe dispozitiv; politicile de domeniu sunt administrate central.","bullets":["Exemplu: grupul Contabilitate primește acces la un folder de departament.","Dezactivarea unui cont la plecarea unui angajat se face centralizat.","Microsoft Entra ID este o platformă de identitate cloud distinctă; Entra join nu este același lucru cu AD DS domain join."]},{"title":"Ordinea de bază: LSDOU","text":"Politicile se procesează în ordinea Local → Site → Domain → OU; OU-urile părinte preced OU-urile copil. În cazul unor setări conflictuale, politica procesată mai târziu are în general prioritate. Nu transforma această regulă într-un „întotdeauna”: Enforced, Block Inheritance, ordinea legăturilor, filtrarea și loopback pot schimba rezultatul.","code":"Local → Site → Domain → OU părinte → OU copil\ngpupdate /force\ngpresult /r","bullets":["gpupdate /force reaplică politicile; nu anulează restricțiile administratorului.","gpresult ajută la verificarea politicilor aplicate; nu modifică politica."],"image":"gpo"}],"cards":[{"front":"AD DS: rolul principal?","back":"Director și administrare centralizată a identităților, computerelor și resurselor."},{"front":"Ce este un DC?","back":"Server care găzduiește AD DS și participă la autentificare și replicare."},{"front":"Ce înseamnă OU?","back":"Organizational Unit: organizare, delegare și asociere de GPO."},{"front":"Ordinea LSDOU?","back":"Local → Site → Domain → Organizational Unit."},{"front":"Cont de domeniu = administrator?","back":"Nu. Identitatea și nivelul de privilegii sunt concepte diferite."}],"quiz":[{"prompt":"Vrei aceeași regulă de securitate pe sute de calculatoare din domeniu. Ce folosești?","options":["Un wallpaper comun","Un SSD comun","GPO"],"answer":2,"why":"Group Policy configurează centralizat calculatoare și utilizatori."},{"prompt":"Ce instrument verifică rezultatul aplicării politicilor?","options":["format","gpresult","ping"],"answer":1,"why":"gpresult afișează informații despre politicile rezultate."},{"prompt":"Care este ordinea de bază corectă?","options":["Local → Site → Domain → OU","OU → Domain → Local → Site","Site → OU → Local → Domain"],"answer":0,"why":"LSDOU este modelul de bază; există excepții de precedență."},{"prompt":"Un angajat are nevoie doar să reseteze parolele unui departament. Ce preferi?","options":["Domain Admin pentru toată lumea","Delegarea sarcinii necesare","Dezactivarea politicilor"],"answer":1,"why":"Privilegiul minim limitează drepturile la sarcina necesară."}],"warning":null,"videos":[{"lesson":"1.2","title":"Local and Group Policies and Precedence","url":"https://drive.google.com/file/d/1aOgCOBnANUPPSfoOvEYOmnWUe7EeqVAT/view","access_verified":false}],"source":"Materialele de curs furnizate de administrator: obiectivul 1.2. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Active Directory și politici","url":"https://learn.microsoft.com/search/?terms=Active%20Directory%20Group%20Policy"}],"minutes":6},{"id":"1.3","chapter":1,"title":"Instalarea Windows","subtitle":"Upgrade, instalare personalizată și configurarea inițială.","sections":[{"title":"Înainte de instalare","text":"Verifică cerințele hardware, ediția și arhitectura, compatibilitatea aplicațiilor și driverele. Salvează fișierele importante și cheia de recuperare BitLocker într-un loc sigur. Creează mediul de instalare dintr-o sursă Microsoft și verifică discul țintă. O instalare pe un dispozitiv de serviciu trebuie autorizată."},{"title":"Upgrade versus Custom","text":"Upgrade poate păstra aplicațiile, setările și fișierele, dacă ruta de actualizare este compatibilă; de regulă pornește din Windows existent. Custom instalează o copie nouă pe partiția aleasă. Nu formatează automat orice partiție: ștergerea sau formatarea este o alegere separată și distructivă.","table":{"headers":["Alegere","Când ajută","Ce verifici"],"rows":[["Upgrade","Trecere compatibilă la o versiune nouă","Ce permite să păstrezi programul de instalare"],["Custom","PC nou sau instalare de la zero","Discul, partiția și backup-ul înainte de ștergere"]]}},{"title":"Pașii inițiali și activarea","text":"Selectează limba, formatul regional și tastatura. Introdu cheia dacă este solicitată sau alege „I don’t have a product key” când este disponibil și vei activa ulterior cu o licență validă. O licență digitală poate reactiva ediția corespunzătoare pe hardware-ul eligibil. Omiterea cheii nu înseamnă că primești o licență gratuită."},{"title":"Regiune, fus orar și sincronizare","text":"Regiunea controlează formate și unele opțiuni locale; fusul orar controlează afișarea orei locale; sincronizarea menține corect ceasul sistemului. Alege locația reală: de exemplu București sau Chișinău, în funcție de dispozitiv și etichetele disponibile. Nu corecta o oră greșită doar schimbând arbitrar fusul.","bullets":["Settings → Time & language → Date & time.","Verifică ora de vară și sincronizarea; pe un PC de domeniu sursa orei poate fi impusă de organizație.","Kerberos depinde de ceasuri sincronizate, nu de afișarea aceluiași fus orar."]},{"title":"Configurare personală sau organizațională","text":"Contul Microsoft este o identitate personală online; contul local există pe dispozitiv. Disponibilitatea opțiunii locale în instalare diferă după ediție și versiune. Configurarea pentru organizație poate folosi Microsoft Entra ID; alăturarea la AD DS este un proces distinct care necesită ediție acceptată, conectivitate, DNS și permisiuni potrivite."}],"cards":[{"front":"Upgrade păstrează întotdeauna toate aplicațiile?","back":"Nu. Depinde de ruta de actualizare; verifică rezumatul instalării."},{"front":"Custom șterge automat tot discul?","back":"Nu. Formatarea/ștergerea se face explicit pe partițiile selectate."},{"front":"Ce faci înainte să ștergi o partiție?","back":"Backup verificat și identificarea sigură a discului/partiției."},{"front":"Fus orar = sincronizarea ceasului?","back":"Nu. Fusul schimbă afișarea locală, sincronizarea menține timpul corect."}],"quiz":[{"prompt":"Care opțiune poate păstra aplicațiile într-o actualizare compatibilă?","options":["Delete partition","Format","Upgrade"],"answer":2,"why":"Upgrade poate păstra aplicațiile și datele dacă ruta este acceptată."},{"prompt":"Ce faci înainte de o instalare curată?","options":["Ștergi toate discurile","Verifici backup-ul și discul țintă","Dezactivezi permanent antivirusul"],"answer":1,"why":"Instalarea poate elimina datele selectate; pregătirea este esențială."},{"prompt":"Omiterea cheii de produs înseamnă licență gratuită?","options":["Da","Nu","Doar pe SSD"],"answer":1,"why":"Activarea și dreptul de utilizare necesită licențiere corespunzătoare."},{"prompt":"Ce setare determină afișarea orei locale?","options":["Fusul orar","Rezoluția","Tipul contului"],"answer":0,"why":"Fusul orar este distinct de regiune și sincronizarea ceasului."}],"warning":null,"videos":[{"lesson":"1.3","title":"Time Zone Options and Upgrade vs. Custom Install","url":"https://drive.google.com/file/d/1kzi3_7a72FTO5CRyo7dUIUTVV02T-cey/view","access_verified":false},{"lesson":"1.3","title":"Microsoft Account vs. Custom Install","url":"https://drive.google.com/file/d/1E4LS6uPjafkhrNvH7_yp4o6HebuHAid8/view","access_verified":false}],"source":"Materialele de curs furnizate de administrator: obiectivul 1.3. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Instalarea Windows","url":"https://learn.microsoft.com/search/?terms=install%20Windows"}],"minutes":6},{"id":"1.4","chapter":1,"title":"Conturi și profiluri de utilizator","subtitle":"Separă identitatea, privilegiile și datele profilului.","sections":[{"title":"Trei tipuri de identitate","text":"Local: definit pe PC. Microsoft: identitate personală pentru Windows și servicii Microsoft. Domain: identitate administrată în AD DS. Un cont organizațional Entra ID este distinct de un cont Microsoft personal.","table":{"headers":["Cont","Administrare","Utilizare"],"rows":[["Local","Pe dispozitiv","PC independent, administrare locală"],["Microsoft","Cont personal online","Integrare cu servicii, sincronizare opțională"],["Domain","Active Directory","Organizații și resurse de domeniu"]]}},{"title":"Cont Microsoft versus local","text":"Contul Microsoft poate sincroniza anumite setări și fișiere când serviciile sunt activate; nu totul se sincronizează automat. Autentificarea Windows cu un cont Microsoft configurat anterior poate funcționa și offline. Un cont local nu garantează absența telemetriei și poate folosi servicii online prin autentificare separată."},{"title":"Standard versus administrator","text":"Tipul identității nu stabilește automat privilegiile. Un utilizator standard își gestionează fișierele și rulează aplicații, dar are nevoie de elevare pentru modificări de sistem. Un administrator are drepturi extinse, însă UAC și permisiunile continuă să conteze; administrarea nu decriptează automat datele EFS sau alte secrete.","bullets":["Folosește cont standard pentru activități zilnice și un cont administrativ pentru sarcini autorizate.","În Settings → Accounts poți gestiona opțiunile disponibile; politicile organizației pot limita schimbările.","Primul cont din instalarea personală este de regulă administrator; provizionarea organizațională poate fi diferită."]},{"title":"Profilul de utilizator","text":"Profilul conține Desktop, Documents, Downloads, AppData și setări specifice utilizatorului. Se află de regulă în C:\\Users\\nume. Contul este identitatea; profilul este mediul său de lucru. Ștergerea unui cont/profil poate șterge date: verifică backup-ul și proprietatea fișierelor înainte de intervenție."},{"title":"UAC în context","text":"La o acțiune ce necesită privilegii, un administrator primește de obicei o cerere de consimțământ, iar un utilizator standard trebuie să furnizeze credențiale administrative autorizate. Politicile pot modifica acest comportament. Nu aproba solicitări neașteptate."}],"cards":[{"front":"Cont sau profil?","back":"Cont = identitate; profil = fișiere și setări de lucru ale utilizatorului."},{"front":"Un cont Microsoft este automat administrator?","back":"Nu. Identitatea și privilegiile sunt independente."},{"front":"Unde se află de regulă profilurile?","back":"C:\\Users\\nume; datele aplicațiilor sunt adesea în AppData."},{"front":"Cont recomandat zilnic?","back":"Standard; elevezi doar sarcinile administrative necesare."}],"quiz":[{"prompt":"Ce conține Desktop și AppData ale utilizatorului?","options":["Socket-ul CPU","DNS-ul","Profilul"],"answer":2,"why":"Profilul păstrează fișiere și setări specifice identității."},{"prompt":"Un cont de domeniu are implicit drepturi de administrator local?","options":["Da","Nu","Numai prin Wi-Fi"],"answer":1,"why":"Drepturile sunt acordate prin grupuri și politici, nu prin simpla apartenență la domeniu."},{"prompt":"Care cont este preferabil pentru utilizare zilnică?","options":["Domain Admin","Standard","Administrator fără UAC"],"answer":1,"why":"Privilegiul minim reduce riscul modificărilor neautorizate."},{"prompt":"Un cont local dezactivează automat toată telemetria Windows?","options":["Da","Nu","Doar dacă are parolă"],"answer":1,"why":"Confidențialitatea se configurează separat; contul local nu este o garanție de zero date trimise."}],"warning":null,"videos":[{"lesson":"1.4","title":"Account Types","url":"https://drive.google.com/file/d/1iPsv9PlTPhCHD8uNmSbIUeQx7t87wPYL/view","access_verified":false}],"source":"Materialele de curs furnizate de administrator: obiectivul 1.4. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Conturi și profiluri de utilizator","url":"https://learn.microsoft.com/search/?terms=Windows%20user%20accounts"}],"minutes":6},{"id":"1.5","chapter":1,"title":"Configurarea desktopului","subtitle":"Start, taskbar, afișaj, ferestre și alimentare.","sections":[{"title":"Meniul Start și comenzile rapide","text":"În Windows 10, Start include lista aplicațiilor și dale; în Windows 11 folosește aplicații fixate și zone care variază după versiune. Clic-dreapta pe aplicație → Pin to Start sau Pin to taskbar. Unpin elimină scurtătura, nu dezinstalează aplicația. Pentru un shortcut clasic: clic-dreapta pe Desktop → New → Shortcut.","image":"start11"},{"title":"Taskbar: organizează accesul","text":"Settings → Personalization → Taskbar permite ajustarea elementelor și comportamentului. Windows 11 permite alinierea pictogramelor la centru sau stânga; opțiunile pentru etichete și grupare diferă după versiune. Windows 10 oferă și repoziționarea barei pe alte laturi.","image":"taskbar"},{"title":"Afișaj: rezoluție versus scalare","text":"Settings → System → Display. Rezoluția definește numărul de pixeli; folosește de regulă rezoluția nativă recomandată. Scalarea mărește textul și elementele fără să schimbe rezoluția. Orientarea poate fi Landscape sau Portrait. Pentru monitoare multiple, identifică-le și aranjează-le în setări ca în realitate.","table":{"headers":["Win + P","Rezultat"],"rows":[["PC screen only","Numai ecranul PC-ului"],["Duplicate","Același conținut"],["Extend","Spațiu de lucru extins"],["Second screen only","Numai al doilea ecran"]]}},{"title":"Gestionarea ferestrelor","text":"Minimize ascunde fereastra, Maximize o extinde, Restore revine la dimensiunea anterioară. Close închide fereastra, dar aplicația poate continua cu alte ferestre/procese. Win + săgeți fixează ferestre; în Windows 11, Win + Z sau survolarea butonului Maximize deschide Snap Layouts.","bullets":["Alt + Tab: comută aplicațiile. Win + D: afișează desktopul.","Snap Groups permite revenirea la un aranjament de ferestre compatibil, nu garantează salvarea documentelor."]},{"title":"Alimentare: ce păstrează sesiunea?","text":"Sleep păstrează sesiunea în RAM cu consum redus; pierderea alimentării poate pierde starea dacă nu există protecție suplimentară. Hibernate salvează sesiunea pe disc. Shutdown închide sesiunea utilizatorului; Fast Startup poate păstra starea nucleului. Restart reinițializează Windows și ajută după actualizări.","table":{"headers":["Stare","Memorie / sesiune","Când"],"rows":[["Sleep","RAM alimentată","Pauză scurtă"],["Hibernate","Fișier pe disc","Pauză lungă, dacă este disponibil"],["Shutdown","Închide aplicațiile utilizatorului","Oprire"],["Restart","Repornește sistemul","Actualizare / depanare"]]}},{"title":"Timp, capac și buton de pornire","text":"Pentru oră: Settings → Time & language → Date & time. Pentru ecran și repaus: System → Power & battery (Windows 11) sau Power & sleep (Windows 10). Control Panel → Power Options permite alegerea acțiunilor butonului și capacului, separat pe baterie și la priză. Opțiunile depind de hardware și politici."}],"cards":[{"front":"Unpin dezinstalează?","back":"Nu. Elimină doar fixarea/scurtătura."},{"front":"Text prea mic pe un ecran 4K?","back":"Ajustează scalarea; păstrează rezoluția nativă."},{"front":"Win + Z?","back":"Snap Layouts în Windows 11."},{"front":"Sleep versus Hibernate?","back":"Sleep păstrează RAM alimentată; Hibernate salvează sesiunea pe disc."},{"front":"Aceeași imagine pe proiector?","back":"Win + P → Duplicate."}],"quiz":[{"prompt":"Vrei două spații diferite pe două monitoare. Alegi:","options":["Extend","Duplicate","PC screen only"],"answer":0,"why":"Extend creează un spațiu de lucru continuu."},{"prompt":"Ce mărește lizibilitatea fără să cobori rezoluția?","options":["Fusul orar","Scalarea","UAC"],"answer":1,"why":"Scalarea ajustează dimensiunea elementelor."},{"prompt":"Ce stare salvează sesiunea pe disc?","options":["Hibernate","Sleep simplu","Minimize"],"answer":0,"why":"Hibernate scrie starea memoriei pe stocare."},{"prompt":"Ce face Unpin from taskbar?","options":["Șterge toate fișierele aplicației","Elimină pictograma fixată","Dezactivează contul"],"answer":1,"why":"Fixarea este doar o cale de acces la aplicație."}],"warning":null,"videos":[{"lesson":"1.5","title":"Start Menu","url":"https://drive.google.com/file/d/1JIn3sM4ZWaWAeSt4Xl-aHd38zxdvRDiZ/view","access_verified":false},{"lesson":"1.5","title":"Taskbar Settings and App Shortcuts","url":"https://drive.google.com/file/d/1ANIPAu9eI5U8wL0oAY-RY_tRzsB7U5bG/view","access_verified":false},{"lesson":"1.5","title":"Display and Time Zone Settings","url":"https://drive.google.com/file/d/1MYQMchgw2XohRb9jeMGv6sMRfsQHEArf/view","access_verified":false},{"lesson":"1.5","title":"Power Settings","url":"https://drive.google.com/file/d/1UUCckOuiiKeM5tgu-zRs7xDmBd5FCB7t/view","access_verified":false}],"source":"Materialele de curs furnizate de administrator: obiectivul 1.5. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Configurarea desktopului","url":"https://learn.microsoft.com/search/?terms=Windows%20desktop%20settings"}],"minutes":6},{"id":"2.1","chapter":2,"title":"Aplicații și funcționalități Windows","subtitle":"Instalează, repară și elimină software în mod controlat.","sections":[{"title":"Permisiuni și surse de instalare","text":"Descarcă software numai din surse de încredere și verifică cerințele. Instalarea pentru toți utilizatorii sau a driverelor necesită de regulă administrator; o aplicație instalată numai în profil poate să nu necesite elevare. Nu toate instalările declanșează UAC. Pe un PC administrat urmează politica organizației."},{"title":"Modify, Repair, Reset și Uninstall","text":"Settings → Apps → Installed apps (Windows 11) sau Apps & features (Windows 10). Opțiunile disponibile depind de aplicație. Pentru programe clasice, Control Panel → Programs and Features poate oferi Change sau Repair.","table":{"headers":["Acțiune","Scop","Atenție"],"rows":[["Modify / Change","Adaugă sau elimină componente","Depinde de installer"],["Repair","Repară instalarea","Verifică ce date păstrează aplicația"],["Reset","Readuce aplicația la starea inițială","Poate șterge date și autentificări"],["Uninstall","Elimină aplicația","Salvează proiectele și setările importante"]]}},{"title":"Funcționalități opționale","text":"„Turn Windows features on or off” gestionează componente precum anumite servicii și platforme Windows. „Optional features” oferă alte componente la cerere; locația în Settings diferă după versiune. Unele funcționalități necesită descărcare, repornire, hardware sau ediție compatibilă. Activează doar ce îți trebuie."},{"title":"Microsoft Store și arhitectura aplicațiilor","text":"Store distribuie și actualizează aplicații; nu conține doar UWP, ci și aplicații desktop. Pe Windows x64, C:\\Program Files este de regulă pentru aplicații native pe 64 de biți, iar C:\\Program Files (x86) pentru multe aplicații x86. Instalările per utilizator și cele împachetate pot folosi alte locații; pe ARM există particularități.","code":"C:\\Program Files\nC:\\Program Files (x86)\n%LOCALAPPDATA%\n%ProgramFiles%\\WindowsApps","bullets":["Nu muta manual folderele programelor ca metodă de reinstalare.","Tipul REG_DWORD sau numele unui folder nu stabilește singur arhitectura aplicației."]},{"title":"Remote Desktop: acces la alt PC","text":"Remote Desktop permite o sesiune la distanță pe un computer configurat să o accepte. Gazda Windows necesită o ediție compatibilă (Home nu găzduiește RDP), utilizator autorizat, conectivitate și reguli firewall potrivite. Clientul se poate deschide cu mstsc.","bullets":["Pe gazda compatibilă: Settings → System → Remote Desktop.","Folosește NLA și acces prin VPN / gateway conform politicii. Nu expune direct RDP pe internet ca soluție rapidă.","Remote Desktop nu este același lucru cu proiectarea ecranului sau simpla partajare a unui fișier."]}],"cards":[{"front":"Repair versus Reset?","back":"Repair încearcă repararea; Reset șterge de regulă datele aplicației și o reinițializează."},{"front":"Unde ajung frecvent aplicațiile x86 pe Windows x64?","back":"C:\\Program Files (x86), dar există excepții și instalări per utilizator."},{"front":"Toate aplicațiile Store sunt UWP?","back":"Nu. Store distribuie și aplicații desktop."},{"front":"Windows Home poate fi gazdă Remote Desktop?","back":"Nu prin funcția RDP gazdă încorporată; poate folosi un client pentru conectare."}],"quiz":[{"prompt":"Vrei să adaugi o componentă unui program instalat. Cauți:","options":["Format","Flush DNS","Modify / Change"],"answer":2,"why":"Modify schimbă componentele instalate dacă installer-ul permite."},{"prompt":"Ce opțiune poate șterge datele locale ale aplicației?","options":["Pin to Start","Minimize","Reset"],"answer":2,"why":"Reset readuce aplicația la starea inițială și poate elimina datele."},{"prompt":"Unde sunt frecvent programele x86 pe Windows x64?","options":["System Volume Information","Program Files (x86)","Doar pe Desktop"],"answer":1,"why":"Aceasta este locația convențională, nu o regulă pentru orice aplicație."},{"prompt":"Ce este necesar pentru gazda Remote Desktop?","options":["Doar cablu HDMI","Ediție acceptată și acces autorizat","Dezactivarea tuturor parolelor"],"answer":1,"why":"RDP necesită configurare, permisiuni și conectivitate sigură."}],"warning":null,"videos":[],"source":"Materialele de curs furnizate de administrator: obiectivul 2.1. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Aplicații și funcționalități Windows","url":"https://learn.microsoft.com/search/?terms=Windows%20apps%20features"}],"minutes":6},{"id":"2.2","chapter":2,"title":"Copilot: capabilități și limite","subtitle":"Asistență AI fără a confunda produsele și permisiunile.","sections":[{"title":"Scopul asistentului","text":"Microsoft Copilot poate răspunde la întrebări, genera și rezuma text, traduce, propune cod și ajuta utilizatorul să găsească instrucțiuni. Funcțiile exacte depind de aplicație, cont, licență, regiune și actualizări. Nu presupune că poate modifica orice setare sau lansa orice depanator pe orice PC."},{"title":"Patru nume, patru contexte","text":"Produsele cu numele Copilot nu au automat aceleași capabilități sau acces la date.","table":{"headers":["Produs / categorie","Rol"],"rows":[["Microsoft Copilot","Asistent conversațional în aplicație și pe web"],["Microsoft 365 Copilot","Asistență în contextul serviciilor organizației, în funcție de licență și permisiuni"],["GitHub Copilot","Asistență la programare în instrumente de dezvoltare"],["Copilot+ PC","Categorie hardware cu NPU și funcții Windows AI compatibile"]]}},{"title":"Deschidere și instalare","text":"Caută Copilot în Start sau verifică aplicațiile instalate. Poate fi fixat în taskbar și poate exista o tastă hardware dedicată. Preinstalarea, comenzile rapide și interfața s-au schimbat în timp; nu memora Alt + Space sau Win + C ca reguli universale. Dacă lipsește, verifică disponibilitatea oficială și politica organizației.","image":"copilot"},{"title":"Depanare și lucrul cu Windows","text":"O cerere bună descrie versiunea Windows, simptomul, mesajul de eroare și ce ai încercat. Copilot poate sugera pași sau direcționa spre Settings / Get Help; executarea directă a acțiunilor există doar unde aplicația și permisiunile o permit. Confirmă singur că instrumentul propus corespunde problemei.","bullets":["Exemplu: „Windows 11, căștile Bluetooth sunt conectate, dar nu se aude sunet. Ce verific întâi?”","Nu executa scripturi generate fără să înțelegi efectul și să ai backup pentru modificări riscante."]},{"title":"Conținut, traducere și cod","text":"Specifică scopul, publicul, limba și formatul: „Rezumă în 5 puncte pentru un începător”. Verifică traducerile importante și testează codul într-un mediu sigur. Generarea de cod într-un chat nu înseamnă că ai automat integrarea GitHub Copilot în IDE."},{"title":"Hardware, confidențialitate și erori","text":"Funcții precum anumite experiențe Recall, traduceri Live Captions sau Cocreator au cerințe hardware și de disponibilitate specifice. Un NPU nu este necesar pentru orice conversație Copilot. AI poate produce informații false cu ton convingător; verifică datele critice în surse oficiale.","bullets":["Nu încărca parole, chei API sau date confidențiale fără autorizare și înțelegerea politicii serviciului.","Accesul la fișiere nu este nelimitat: depinde de permisiuni și conținutul partajat.","Protecțiile datelor personale și comerciale diferă; verifică termenii produsului folosit."]}],"cards":[{"front":"Copilot poate greși?","back":"Da. Verifică informațiile critice și comenzile înainte de executare."},{"front":"Copilot+ PC este același lucru cu aplicația Copilot?","back":"Nu. Este o categorie hardware, nu un sinonim pentru chatbot."},{"front":"Ce trebuie să conțină un prompt de depanare?","back":"Versiune, simptom, mesaj de eroare, context și pașii deja încercați."},{"front":"Poate accesa automat orice fișier?","back":"Nu. Accesul depinde de produs, integrare, partajare și permisiuni."}],"quiz":[{"prompt":"Copilot propune o comandă care șterge fișiere. Ce faci?","options":["O execuți pentru că este AI","Verifici efectele și pregătești backup / mediu de test","O trimiți tuturor colegilor"],"answer":1,"why":"Conținutul generat nu înlocuiește verificarea tehnică."},{"prompt":"Ce produs este axat pe ajutor în IDE?","options":["GitHub Copilot","BitLocker","Task Manager"],"answer":0,"why":"GitHub Copilot oferă integrare în instrumente de dezvoltare."},{"prompt":"Orice funcție AI necesită Copilot+ PC?","options":["Nu","Da","Doar traducerea textului"],"answer":0,"why":"Multe funcții conversaționale sunt procesate prin servicii cloud."},{"prompt":"Ce limitează accesul la date organizaționale?","options":["Doar rezoluția","Nimic","Permisiunile și configurația produsului"],"answer":2,"why":"Copilot nu trebuie tratat ca un acces universal la toate datele."}],"warning":"Lecție dependentă de versiune: verifică funcțiile disponibile în aplicația și ediția folosite la examen.","videos":[],"source":"Materialele de curs furnizate de administrator: obiectivul 2.2. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Copilot: capabilități și limite","url":"https://learn.microsoft.com/search/?terms=Microsoft%20Copilot%20Windows"}],"minutes":6},{"id":"2.3","chapter":2,"title":"Registrul Windows","subtitle":"Baza ierarhică de configurare: chei, valori și precauții.","sections":[{"title":"Rolul registrului","text":"Windows Registry este o bază de date ierarhică pentru configurarea Windows, aplicațiilor și utilizatorilor. Include preferințe, servicii, drivere, asocieri de fișiere și politici. Nu toate aplicațiile își păstrează toate setările aici: fișierele de configurare continuă să existe."},{"title":"Chei, subchei și valori","text":"Gândește-te la chei ca la foldere. O cheie poate conține subchei și valori. O valoare are un nume, un tip și date. Calea folosește backslash. Regedit afișează arborele în stânga și valorile cheii selectate în dreapta.","code":"HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Windows","image":"registry"},{"title":"Cele cinci chei rădăcină","text":"Cheile rădăcină predefinite nu sunt toate fișiere fizice independente. Un hive este o unitate de registru cu propriul set de chei și date, adesea susținută de fișiere pe disc; nu îl confunda cu orice rădăcină afișată.","table":{"headers":["Cheie","Abreviere","Scop"],"rows":[["HKEY_LOCAL_MACHINE","HKLM","Configurare la nivelul computerului"],["HKEY_CURRENT_USER","HKCU","Setările utilizatorului curent; vedere în HKU"],["HKEY_USERS","HKU","Hive-uri de utilizator încărcate, nu automat toate profilurile existente"],["HKEY_CLASSES_ROOT","HKCR","Vedere combinată pentru asocieri de fișiere / COM din HKLM și HKCU"],["HKEY_CURRENT_CONFIG","HKCC","Vedere spre profilul hardware curent din HKLM"]]}},{"title":"Tipuri de valori","text":"Tipul arată cum se interpretează datele, nu arhitectura Windows. REG_DWORD este folosit și pe Windows x64, iar REG_QWORD poate exista și pe Windows pe 32 de biți. Semnificația valorii 0 sau 1 depinde de setarea documentată.","table":{"headers":["Tip","Conținut"],"rows":[["REG_SZ","Șir text terminat cu nul"],["REG_EXPAND_SZ","Text cu variabile de mediu, precum %SystemRoot%"],["REG_MULTI_SZ","Mai multe șiruri text"],["REG_DWORD","Număr pe 32 de biți"],["REG_QWORD","Număr pe 64 de biți"],["REG_BINARY","Date binare"]]}},{"title":"Acces și lucru sigur","text":"Win + R → regedit deschide editorul; modificările sunt limitate de permisiuni și pot necesita elevare. Preferă Settings sau politici documentate când există. Pentru examen, obiectivul principal este să explici scopul registrului, nu să aplici tweak-uri.","bullets":["Înainte de modificare: documentează cheia și valoarea inițială, obține autorizarea și pregătește o metodă de recuperare.","Exportul unei ramuri .reg este util, dar nu este o copie completă recuperabilă a întregului sistem.","Importul .reg combină datele: nu elimină automat valorile nou create și nu reface toate permisiunile.","Un punct de restaurare, dacă este disponibil, sau un backup adecvat adaugă protecție; verifică posibilitatea reală de recuperare.","Nu rula fișiere .reg necunoscute și nu folosi registry cleaners ca soluție universală."]}],"cards":[{"front":"Registrul păstrează ce?","back":"Configurări Windows, aplicații și preferințe de utilizator."},{"front":"HKCU versus HKLM?","back":"HKCU: utilizatorul curent. HKLM: configurarea computerului."},{"front":"REG_DWORD este numai pentru Windows 32-bit?","back":"Nu. Este un tip numeric de 32 de biți, utilizabil și pe Windows x64."},{"front":"Importul .reg restaurează exact tot sistemul?","back":"Nu. Combină datele și nu anulează automat toate modificările."},{"front":"HKU conține toate conturile de pe disc?","back":"Nu neapărat. Arată hive-urile utilizatorilor încărcate."}],"quiz":[{"prompt":"Unde cauți preferințele utilizatorului curent?","options":["HKCU","HKCC","Un port PCIe"],"answer":0,"why":"HKEY_CURRENT_USER reprezintă setările utilizatorului curent."},{"prompt":"Ce tip acceptă variabile precum %SystemRoot%?","options":["REG_EXPAND_SZ","REG_DWORD","REG_QWORD"],"answer":0,"why":"REG_EXPAND_SZ poate conține variabile de mediu."},{"prompt":"Ce trebuie reținut despre exportul .reg?","options":["Garantează restaurarea completă","Este util, dar nu înlocuiește un backup adecvat","Șterge registrul"],"answer":1,"why":"Exportul/importul nu recreează exact toate stările și permisiunile."},{"prompt":"REG_DWORD indică:","options":["Obligatoriu o aplicație x86","Un cont de domeniu","O valoare numerică de 32 de biți"],"answer":2,"why":"Dimensiunea tipului de date nu stabilește arhitectura aplicației sau a OS-ului."}],"warning":"Nu modifica registrul pentru a exersa pe calculatorul principal. Folosește un laborator cu recuperare pregătită.","videos":[],"source":"Materialele de curs furnizate de administrator: obiectivul 2.3. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Registrul Windows","url":"https://learn.microsoft.com/search/?terms=Windows%20registry"}],"minutes":6},{"id":"2.4","chapter":2,"title":"Conectarea perifericelor","subtitle":"Recunoaște conectorul și verifică semnalul, direcția și funcțiile.","sections":[{"title":"Analogic versus digital","text":"VGA și conexiunile AUX obișnuite transportă semnale analogice. HDMI, DisplayPort și S/PDIF transportă semnale digitale. Semnalele digitale au toleranță la zgomot, nu imunitate la orice eroare. Un conector care se potrivește fizic nu garantează compatibilitatea semnalelor.","image":"signal"},{"title":"HDMI și DisplayPort","text":"HDMI transmite de regulă video și audio digital; dimensiunile uzuale sunt Type A (standard), Type C (mini) și Type D (micro). DisplayPort există full-size și Mini DisplayPort; poate transporta audio și video. MST permite mai multe ecrane dacă sursa, sistemul și monitoarele/hubul suportă funcția.","table":{"headers":["Conexiune","Semnal","De verificat"],"rows":[["HDMI","Video + audio digital","Rezoluție, refresh, HDR, port și cablu"],["DisplayPort","Video + audio digital","Versiune, MST/DSC și suportul dispozitivelor"],["Mini DisplayPort","Formă mică DP","Nu este automat Thunderbolt"]]},"image":"hdmi"},{"title":"DVI și VGA","text":"DVI-D transportă digital, DVI-A analogic, iar DVI-I poate transporta ambele. Single Link și Dual Link diferă prin capacitate; verifică pinii și cerințele. VGA are 15 pini pe trei rânduri și transportă video analogic, nu audio. Nu identifica un port numai după culoare.","image":"dvi"},{"title":"USB: formă versus versiune","text":"USB-A și USB-B au variante standard, mini și micro, inclusiv forme istorice mai rare. USB 3.x a adăugat contacte și variante precum USB-B 3.x și Micro-B 3.x. „USB 3.0” este o specificație de transfer, nu un nume pentru orice conector albastru. USB-C este conectorul reversibil; viteza, video și alimentarea depind de implementare.","bullets":["Mini-A/Micro-A sunt tipuri istorice; nu le confunda cu Mini-B/Micro-B după nume.","Un cablu USB-C poate fi limitat la USB 2.0 sau poate să nu suporte video.","Verifică standardul de date, DisplayPort Alt Mode / Thunderbolt, USB Power Delivery și puterea cablului."],"image":"usb"},{"title":"Thunderbolt și USB-C","text":"Thunderbolt 1/2 folosesc forma Mini DisplayPort; Thunderbolt 3/4/5 folosesc USB-C. Thunderbolt combină transport de date și afișaj cu cerințe specifice standardului. Nu orice port USB-C este Thunderbolt, iar viteza reală este limitată de cea mai slabă componentă din lanț.","image":"thunderbolt"},{"title":"Audio: S/PDIF optic și AUX","text":"S/PDIF optic folosește de obicei TOSLINK și transportă audio digital; poate transmite stereo PCM și anumite formate comprimate multicanal, nu orice format surround fără pierderi. AUX de 3,5 mm transportă de regulă audio analogic; TRS și TRRS diferă, inclusiv prin suportul microfonului.","image":"audio"},{"title":"Adaptoare și convertoare","text":"Un adaptor pasiv funcționează doar când sursa oferă deja semnal compatibil, de exemplu DVI-I analogic spre VGA sau anumite porturi DP++ spre HDMI. Conversia HDMI/DP digital spre VGA analogic necesită conversie activă. Verifică direcția: HDMI → VGA nu înseamnă automat VGA → HDMI.","bullets":["Pentru USB-C → HDMI/DP, verifică explicit ieșirea video a portului; simpla formă USB-C nu este suficientă.","Convertoarele pot necesita alimentare și pot limita rezoluția, refresh-ul sau audio.","Ordinea de verificare: sursă → port → cablu/adaptor → intrare monitor → setări."],"image":"adapter"}],"cards":[{"front":"VGA transmite audio?","back":"Nu. VGA transportă video analogic."},{"front":"USB-C garantează video și încărcare rapidă?","back":"Nu. Verifică funcțiile portului și cablului."},{"front":"DVI-I versus DVI-D?","back":"DVI-I poate include analogic și digital; DVI-D este digital."},{"front":"Thunderbolt 3/4 folosește ce formă?","back":"USB-C, dar nu orice USB-C este Thunderbolt."},{"front":"HDMI spre VGA: pasiv?","back":"Necesită conversie digital–analogică activă."}],"quiz":[{"prompt":"Un port USB-C nu afișează imagine prin adaptor. Ce verifici întâi?","options":["Suportul ieșirii video și cablul/adaptorul","Doar culoarea mufei","Numele utilizatorului"],"answer":0,"why":"Forma USB-C nu garantează DisplayPort Alt Mode sau Thunderbolt."},{"prompt":"Ce conector este analogic video?","options":["HDMI","VGA","DisplayPort"],"answer":1,"why":"VGA este analogic și nu transportă audio."},{"prompt":"Ce DVI include semnale analogice și digitale?","options":["DVI-I","DVI-D","Niciunul"],"answer":0,"why":"I înseamnă Integrated; DVI-D este numai digital."},{"prompt":"Ce contează la un convertor?","options":["Doar să intre mufa","Doar lungimea numelui","Direcția, semnalul și capabilitățile"],"answer":2,"why":"Compatibilitatea mecanică nu este suficientă pentru conversie."}],"warning":null,"videos":[{"lesson":"2.4","title":"VGA","url":"https://drive.google.com/file/d/1QRBDqxIRPbaKSFlLfLALkRZ2CEgAC0fV/view","access_verified":false},{"lesson":"2.4","title":"USB-C and Converting Between Connection Types","url":"https://drive.google.com/file/d/1nA7Kka0OYejJTcX1eZ6jUHPQkm1QkMRZ/view","access_verified":false},{"lesson":"2.4","title":"Peripheral Device Connections","url":"https://drive.google.com/file/d/1Os-I1rDEFq5_-VPiAJn_W4LiVhCvSJ_d/view","access_verified":false}],"source":"Materialele de curs furnizate de administrator: obiectivul 2.4. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Conectarea perifericelor","url":"https://learn.microsoft.com/search/?terms=USB%20DisplayPort%20HDMI"}],"minutes":7},{"id":"2.5","chapter":2,"title":"Proiecție și proprietăți de afișare","subtitle":"Alege modul potrivit și obține o imagine clară.","sections":[{"title":"Conectare și proiectare","text":"Pentru cablu verifică portul, cablul și intrarea selectată pe monitor. Win + P deschide modurile PC screen only, Duplicate, Extend și Second screen only. Win + K caută ecrane wireless compatibile; proiectarea Miracast depinde de hardware, drivere și receptor. Bluetooth simplu nu este echivalent cu Miracast."},{"title":"Duplicate versus Extend","text":"Duplicate arată același conținut pe ecrane și poate limita modurile disponibile la cele compatibile. Extend oferă spații de lucru distincte; în Settings → System → Display poți identifica ecranele, stabili monitorul principal și ajusta aranjarea."},{"title":"Rezoluție, raport de aspect și refresh","text":"1920 × 1080 exprimă lățime × înălțime în pixeli; 16:9 este raportul de aspect. Rezoluția nativă oferă de regulă cea mai clară imagine. Refresh rate în Hz este frecvența actualizării imaginii, nu rezoluția. Portul, cablul, adaptorul și monitorul trebuie să suporte combinația aleasă.","table":{"headers":["Setare","Modifică"],"rows":[["Resolution","Numărul de pixeli"],["Scale","Dimensiunea textului și elementelor"],["Orientation","Landscape / Portrait"],["Refresh rate","Actualizările imaginii pe secundă"]]}},{"title":"ClearType și lizibilitate","text":"Caută „Adjust ClearType text” pentru a calibra afișarea textului pe ecrane compatibile. Dacă textul este prea mic, verifică mai întâi scalarea; dacă este neclar, verifică rezoluția nativă, conexiunea și apoi reglajele de text. ClearType nu repară un cablu defect sau o rezoluție nepotrivită."},{"title":"Flux rapid de depanare","text":"Lipsă imagine: alimentare și intrare monitor → cablu/port → Win + P → Detect în Display → driver și compatibilitate. Imagine întinsă: rezoluție și raport de aspect. Fereastra „pierdută”: verifică aranjarea monitoarelor sau folosește Win + Shift + săgeată pentru mutarea ferestrei."}],"cards":[{"front":"Win + K?","back":"Conectare/cast la afișaje wireless compatibile."},{"front":"Extend versus Duplicate?","back":"Extend: spații distincte. Duplicate: aceeași imagine."},{"front":"Hz versus pixeli?","back":"Hz = rata de refresh; pixeli = rezoluție."},{"front":"ClearType repară orice imagine neclară?","back":"Nu. Este destinat randării textului; verifică întâi rezoluția și conexiunea."}],"quiz":[{"prompt":"Pentru prezentare cu aceeași imagine pe proiector alegi:","options":["Extend","Second screen only obligatoriu","Duplicate"],"answer":2,"why":"Duplicate reproduce același conținut."},{"prompt":"Ce exprimă 60 Hz?","options":["60 GB stocare","Lățimea în pixeli","Rata de actualizare a ecranului"],"answer":2,"why":"Hz măsoară frecvența refresh-ului."},{"prompt":"Pentru ecran wireless compatibil folosești:","options":["Win + K","Ctrl + C","gpupdate"],"answer":0,"why":"Win + K deschide interfața Cast."},{"prompt":"Textul este mic pe un monitor 4K. Ce ajustezi?","options":["Scalarea","Cheia Wi-Fi","Tipul NTFS"],"answer":0,"why":"Scalarea mărește elementele fără a coborî rezoluția nativă."}],"warning":null,"videos":[],"source":"Materialele de curs furnizate de administrator: obiectivul 2.5. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Proiecție și proprietăți de afișare","url":"https://learn.microsoft.com/search/?terms=Windows%20display"}],"minutes":6},{"id":"3.1","chapter":3,"title":"Cloud și configurarea stocării","subtitle":"Colaborare online, sincronizare și organizarea discurilor.","sections":[{"title":"Cloud: servicii și modele","text":"Cloud înseamnă resurse furnizate prin rețea, cu responsabilități împărțite între client și furnizor. Abonamentul sau plata după consum depind de produs; nu orice cloud are aceeași taxare.","table":{"headers":["Model","Furnizorul oferă","Exemplu"],"rows":[["IaaS","Infrastructură: calcul, rețea, stocare","Mașină virtuală Azure"],["PaaS","Platformă pentru dezvoltare și rulare","Azure App Service"],["SaaS","Aplicație utilizabilă ca serviciu","Microsoft 365"]]},"image":"cloud-models"},{"title":"Obiecte, fișiere și blocuri","text":"Object storage gestionează obiecte cu date și metadate; file storage folosește fișiere și directoare partajate; block storage oferă volume de blocuri pentru sisteme și aplicații. Alege în funcție de acces și aplicație, nu doar după capacitate.","image":"cloud-types"},{"title":"Serviciile Microsoft","text":"Azure oferă servicii cloud de infrastructură și platformă. OneDrive gestionează fișiere individuale și sincronizare; SharePoint oferă biblioteci și colaborare de echipă. Outlook gestionează e-mail/calendar; Teams facilitează comunicarea și colaborarea; Windows 365 furnizează Cloud PC. Microsoft 365 reunește aplicații și servicii, în funcție de plan."},{"title":"Partajarea fișierelor","text":"La Share, verifică destinatarii și dreptul View sau Edit. „Anyone with the link” poate permite accesul prin redistribuirea linkului; pentru date sensibile preferă persoane specifice și politici aprobate. Expirarea, parola sau blocarea descărcării depind de abonament și configurație.","bullets":["Manage access permite revizuirea și revocarea accesului.","Un link trimis nu trebuie presupus privat. Verifică identitatea și permisiunile.","Blocarea descărcării nu împiedică orice formă de copiere, precum fotografierea ecranului."],"image":"cloud-share"},{"title":"OneDrive Files On-Demand","text":"Online-only: pictograma nor, necesită descărcare pentru acces. Locally available: cerc cu contur și bifă, copie locală disponibilă. Always keep on this device: cerc verde plin, fișier păstrat local. Free up space elimină copia locală și păstrează fișierul online; Delete poate sincroniza ștergerea.","bullets":["Verifică starea sincronizării și spațiul disponibil înainte de lucru offline.","Sincronizarea nu este singură un backup independent: ștergerile și modificările pot fi replicate."],"image":"onedrive"},{"title":"Partiționare și stil de disc","text":"Partiționarea împarte discul în regiuni logice; formatarea creează sistemul de fișiere pe un volum. GPT este stilul modern folosit la instalările Windows UEFI. MBR are limite precum aproximativ 2 TiB cu sectoare de 512 octeți și patru partiții primare sau combinație cu una extinsă.","bullets":["Deschide Disk Management cu diskmgmt.msc; identifică discul după capacitate și model, nu doar după număr.","Nu inițializa și nu formata un disc cu date necunoscute/RAW înainte de un plan de recuperare.","O a doua partiție pe același disc nu protejează de defectarea discului."],"image":"bios"},{"title":"NTFS, FAT32 și exFAT","text":"Sistemul de fișiere stabilește funcțiile și compatibilitatea volumului.","table":{"headers":["Format","Avantaj","Limitare importantă"],"rows":[["NTFS","Permisiuni, jurnalizare, funcții Windows","Compatibilitate diferită pe alte dispozitive"],["FAT32","Compatibilitate largă cu echipamente vechi","Fișier individual sub 4 GiB"],["exFAT","Fișiere mari pe medii externe","Nu oferă ACL NTFS sau jurnalizare NTFS"]]}},{"title":"Atribute, copiere și mutare","text":"Read-only, Hidden și Archive sunt atribute, nu echivalente cu permisiunile de securitate. NTFS poate oferi compresie și criptare EFS; EFS necesită protejarea certificatului și cheii. Copierea creează de regulă un obiect care moștenește permisiunile destinației; mutarea pe același volum NTFS păstrează de regulă permisiunile. Între volume se comportă uzual ca o copiere și ștergere.","bullets":["Instrumentele și opțiunile de copiere pot păstra explicit alte permisiuni sau atribute.","Pe FAT32/exFAT nu poți păstra permisiunile NTFS ca ACL funcționale.","Formatarea și comanda diskpart clean pot distruge accesul la date; nu sunt pași de depanare fără backup."]}],"cards":[{"front":"IaaS, PaaS, SaaS?","back":"Infrastructură, platformă, aplicație ca serviciu."},{"front":"Nor în OneDrive?","back":"Fișier online-only; trebuie descărcat pentru utilizare offline."},{"front":"Delete versus Free up space?","back":"Delete poate șterge și din cloud; Free up space păstrează fișierul online."},{"front":"Fișier de 6 GB pe FAT32?","back":"Nu. Limita individuală este sub 4 GiB; alege un format compatibil cu fișiere mari."},{"front":"O partiție separată este backup?","back":"Nu. Defectarea discului poate afecta toate partițiile."}],"quiz":[{"prompt":"Vrei un fișier disponibil fără internet. Alegi:","options":["Always keep on this device și verifici descărcarea","Delete","Doar trimiți linkul"],"answer":0,"why":"Păstrarea locală presupune sincronizare/descărcare finalizată."},{"prompt":"Ce format permite ACL native Windows?","options":["NTFS","FAT32","Niciunul"],"answer":0,"why":"NTFS oferă permisiuni de securitate pentru fișiere și foldere."},{"prompt":"Ce model oferă o aplicație completă?","options":["SaaS","IaaS","MBR"],"answer":0,"why":"Software as a Service furnizează aplicația, nu doar infrastructura."},{"prompt":"Un disc cu fișiere importante apare RAW. Ce faci întâi?","options":["Formatezi rapid","Protejezi datele și pregătești recuperarea","Rulezi clean"],"answer":1,"why":"Scrierile și formatarea pot reduce șansele de recuperare."}],"warning":"Formatarea, inițializarea și ștergerea partițiilor sunt operațiuni distructive. Exercițiile se fac pe un disc de laborator.","videos":[{"lesson":"3.1","title":"Cloud Storage","url":"https://drive.google.com/file/d/1gRs-pq09h2OzZUwyTuTQymu-CpURGL6A/view","access_verified":false}],"source":"Materialele de curs furnizate de administrator: obiectivul 3.1. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Cloud și configurarea stocării","url":"https://learn.microsoft.com/search/?terms=OneDrive%20Files%20On-Demand"}],"minutes":8},{"id":"3.2","chapter":3,"title":"Partajare și permisiuni","subtitle":"NTFS, Share și accesul efectiv la resurse.","sections":[{"title":"Două niveluri de control","text":"Permisiunile NTFS se aplică fișierelor/directoarelor de pe volume NTFS, inclusiv la acces local. Permisiunile Share se aplică accesului prin partajarea de rețea. La acces remote trebuie să permită ambele niveluri; accesul rezultat este intersecția lor."},{"title":"Permisiuni uzuale","text":"Aplică permisiunile preferabil grupurilor și doar la nivelul necesar.","table":{"headers":["Nivel","Permisiuni / idee"],"rows":[["Share","Read, Change, Full Control"],["NTFS Read / Read & execute","Citire, listare și eventual execuție"],["NTFS Write","Creare/scriere potrivit drepturilor exacte"],["NTFS Modify","Citire, scriere și ștergere"],["NTFS Full control","Include modificarea permisiunilor și alte drepturi extinse"]]}},{"title":"Moștenire și acces efectiv","text":"Folderele pot transmite permisiuni obiectelor copil. Accesul depinde de grupurile utilizatorului, regulile explicite/moștenite și ordinea ACL. „Deny câștigă întotdeauna” este o simplificare insuficientă; folosește Properties → Security → Advanced → Effective Access pentru a investiga.","bullets":["Exemplu simplu: Share Read și NTFS Modify → prin rețea utilizatorul este limitat la citire.","Schimbarea proprietarului nu acordă automat acces la tot și nu decriptează EFS.","Nu acorda Everyone Full Control ca soluție implicită la o eroare de acces."]},{"title":"Configurarea unei partajări","text":"Pe o rețea de încredere: verifică profilul și politicile, Network Discovery și File and Printer Sharing când sunt necesare. Properties → Sharing → Advanced Sharing permite configurarea partajării și a permisiunilor. Configurează separat Security pentru NTFS. Public folders sunt o opțiune de partajare, nu o garanție de acces privat."},{"title":"Cale UNC și unitate mapată","text":"O cale UNC identifică serverul și partajarea. Map network drive asociază o literă acelei resurse; nu copiază datele local și nu oferă acces offline de la sine. Pentru probleme verifică rețeaua, DNS, disponibilitatea SMB, credențialele și ambele seturi de permisiuni.","code":"\\\\server\\partajare\n\\\\server\\partajare\\document.docx","bullets":["O eroare „Access denied” poate avea altă cauză decât o resursă care nu este găsită.","Nu activa SMB1 ca remediu de rutină pentru echipamente vechi; preferă SMB2/3 și actualizare/escaladare."]}],"cards":[{"front":"Local: contează Share?","back":"Nu pentru acces direct la fișier; NTFS se aplică în continuare."},{"front":"Remote: Share Read + NTFS Modify?","back":"Citire prin partajare, deoarece ambele niveluri trebuie să permită operațiunea."},{"front":"Map network drive copiază fișierele?","back":"Nu. Creează o cale de acces printr-o literă de unitate."},{"front":"Taking ownership decriptează EFS?","back":"Nu. Criptarea necesită cheia corespunzătoare."}],"quiz":[{"prompt":"Share permite Read, NTFS permite Modify. Prin rețea poți edita?","options":["Da","Nu","Doar după Minimize"],"answer":1,"why":"Nivelul Share limitează accesul remote la citire."},{"prompt":"Ce reprezintă \\\\server\\date?","options":["Partiție GPT","Cheie HKCU","Cale UNC"],"answer":2,"why":"UNC identifică o resursă partajată de rețea."},{"prompt":"Ce este preferabil la acordarea accesului?","options":["Everyone Full Control peste tot","Ștergerea ACL","Permisiuni grupurilor după nevoie"],"answer":2,"why":"Grupurile și privilegiul minim simplifică administrarea."},{"prompt":"Ce verifici pentru acces efectiv NTFS?","options":["Doar rezoluția","Numai numele folderului","Effective Access și apartenența la grupuri"],"answer":2,"why":"Permisiunile explicite, moștenite și grupurile influențează accesul."}],"warning":null,"videos":[],"source":"Materialele de curs furnizate de administrator: obiectivul 3.2. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Partajare și permisiuni","url":"https://learn.microsoft.com/search/?terms=NTFS%20share%20permissions"}],"minutes":6},{"id":"4.1","chapter":4,"title":"Microsoft Defender Firewall","subtitle":"Filtrarea traficului și excepții precise.","sections":[{"title":"Firewall nu înseamnă antivirus","text":"Windows Security este interfața centrală de securitate. Microsoft Defender Antivirus detectează amenințări software; Microsoft Defender Firewall filtrează traficul de rețea al dispozitivului. Firewall-ul de pe PC completează protecția routerului, nu o înlocuiește."},{"title":"Inbound, outbound și stare","text":"În configurația implicită uzuală, conexiunile inbound nesolicitate sunt blocate dacă nu există o regulă permisivă; outbound este în general permis dacă nu există o regulă de blocare. Firewall-ul urmărește starea conexiunilor și poate permite răspunsurile la comunicații inițiate local. Politicile pot schimba valorile implicite."},{"title":"Domain, Private și Public","text":"Acestea sunt cele trei profiluri firewall. „Guest” nu este un al patrulea profil distinct; rețelele de oaspeți se tratează de regulă ca Public.","table":{"headers":["Profil","Când","Precauție"],"rows":[["Domain","Rețea identificată prin autentificare la AD DS","Determinat automat; reguli organizaționale"],["Private","Rețea locală cunoscută și de încredere","Partajarea trebuie configurată, nu este garantată automat"],["Public","Cafenea, aeroport, rețea necunoscută","Evită excepțiile de partajare nejustificate"]]}},{"title":"Permite o aplicație, nu dezactiva protecția","text":"Windows Security → Firewall & network protection → Allow an app through firewall → Change settings. Selectează aplicația sau executabilul autorizat și doar profilurile necesare. O excepție pentru o aplicație nu este o evaluare antivirus și nu o face automat sigură."},{"title":"Reguli avansate și depanare","text":"wf.msc deschide consola avansată. Poți defini programul, direcția, protocolul, portul, adresele și profilurile. O regulă de port nu creează singură un serviciu care ascultă. Investighează regulile și jurnalele înainte de a opri firewall-ul.","code":"wf.msc","image":"firewall"},{"title":"Oprire temporară: excepție, nu soluție","text":"Dacă un test autorizat într-un mediu controlat cere oprire temporară: alege profilul activ, notează starea, limitează durata și reactivează imediat. Preferă o regulă îngustă. Pe dispozitive administrate nu ocoli politicile. Restore defaults elimină reguli personalizate: documentează configurația înainte."}],"cards":[{"front":"Firewall versus antivirus?","back":"Firewall filtrează trafic; antivirusul detectează și tratează malware."},{"front":"Profil pentru Wi-Fi de cafenea?","back":"Public."},{"front":"Guest este profil firewall distinct?","back":"Nu. Profilurile sunt Domain, Private și Public."},{"front":"Consola avansată?","back":"wf.msc."}],"quiz":[{"prompt":"O aplicație legitimă este blocată. Ce preferi?","options":["O regulă precisă pentru aplicație și profil","Firewall oprit permanent","Toate porturile permise"],"answer":0,"why":"Excepțiile limitate păstrează restul protecției."},{"prompt":"Ce profil alegi pe o rețea necunoscută?","options":["Public","Private","Domain manual"],"answer":0,"why":"Public este potrivit rețelelor fără încredere."},{"prompt":"Ce filtrează firewall-ul?","options":["Doar fișiere Word","Temperatura CPU","Traficul de rețea"],"answer":2,"why":"Protecția este bazată pe reguli de comunicare."},{"prompt":"O regulă care permite un port pornește automat un server?","options":["Nu","Da","Doar pe Wi-Fi"],"answer":0,"why":"Un serviciu trebuie să ruleze și să asculte separat pe acel port."}],"warning":null,"videos":[],"source":"Materialele de curs furnizate de administrator: obiectivul 4.1. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Microsoft Defender Firewall","url":"https://learn.microsoft.com/search/?terms=Windows%20Firewall"}],"minutes":6},{"id":"4.2","chapter":4,"title":"Autentificare și Windows Hello","subtitle":"Factori diferiți, parole și opțiuni de conectare.","sections":[{"title":"Cei trei factori","text":"Ceva ce știi: parolă. Ceva ce ai: cheie de securitate sau dispozitiv/token. Ceva ce ești: amprentă sau față. MFA combină factori din categorii diferite; două parole nu sunt MFA. Implementările passwordless pot combina posesia cheii cu verificarea locală.","image":"mfa"},{"title":"Windows Hello","text":"Hello există în Windows 10 și 11. Oferă PIN și, cu hardware compatibil, față sau amprentă. PIN-ul Hello este legat de dispozitiv și de protejarea credențialei locale; nu este pur și simplu parola online mai scurtă. Recunoașterea facială cere cameră compatibilă, de regulă IR, nu orice webcam.","image":"hello"},{"title":"TPM și biometrie","text":"TPM ajută la protejarea cheilor criptografice. Datele biometrice Hello sunt procesate și protejate local; nu presupune că șablonul biometric este întotdeauna stocat fizic în TPM. Biometria nu poate fi schimbată ca o parolă și necesită protecție atentă."},{"title":"Configurarea conectării","text":"Settings → Accounts → Sign-in options afișează metodele disponibile. Configurează mai întâi metoda de recuperare și urmează politica organizației. Opțiunile pot include PIN, biometrică, parolă și cheie de securitate. Dynamic Lock poate bloca PC-ul când dispozitivul Bluetooth asociat se îndepărtează; nu înlocuiește Win + L când pleci de la birou."},{"title":"Parole, Authenticator și phishing","text":"Folosește parole lungi, unice, preferabil generate și păstrate într-un manager de parole. Nu reutiliza parola și nu aproba notificări MFA neașteptate. Aplicațiile Authenticator pot genera coduri TOTP sau primi cereri de aprobare, în funcție de serviciu. Codurile TOTP pot fi furate prin phishing; cheile FIDO2/passkeys oferă rezistență la phishing prin legarea de site.","bullets":["Nu divulga parola sau codul unui pretins agent de suport.","Păstrează codurile de recuperare în siguranță, separat de accesul pe care îl recuperează.","O notificare neașteptată trebuie respinsă și raportată; nu presupune că aprobarea „repară” contul."]}],"cards":[{"front":"Parolă + altă parolă = MFA?","back":"Nu. Sunt din aceeași categorie: ceva ce știi."},{"front":"Windows Hello este numai pe Windows 11?","back":"Nu. Este disponibil și pe Windows 10, cu cerințe specifice metodei."},{"front":"Orice webcam acceptă Hello Face?","back":"Nu. Necesită hardware compatibil."},{"front":"Un cod TOTP este imposibil de furat prin phishing?","back":"Nu. Poate fi retransmis de un atacator."},{"front":"Ce faci cu o aprobare MFA neașteptată?","back":"O respingi și investighezi/raportezi tentativa."}],"quiz":[{"prompt":"Ce combinație folosește categorii diferite?","options":["Două parole","Parolă și întrebare secretă","Parolă și cheie de securitate"],"answer":2,"why":"Cunoaștere + posesie reprezintă factori diferiți."},{"prompt":"PIN-ul Windows Hello este în principal:","options":["Parola tuturor conturilor","Un nume DNS","Legat de dispozitiv"],"answer":2,"why":"Hello protejează accesul la credențiala de pe dispozitiv."},{"prompt":"Primești o aprobare MFA neinițiată. Ce faci?","options":["Respingi și raportezi","Aprobi ca să dispară","Trimiți codul prin mesaj"],"answer":0,"why":"Poate fi o încercare de compromitere sau MFA fatigue."},{"prompt":"Ce caracteristică este importantă pentru o parolă?","options":["Aceeași peste tot","Unică și lungă","Numele utilizatorului"],"answer":1,"why":"Unicitatea limitează atacurile între conturi, iar lungimea crește rezistența."}],"warning":null,"videos":[{"lesson":"4.2","title":"Types of Authentication","url":"https://drive.google.com/file/d/1jFRIGuZhC2RalJ_cuTs4MJBusWC-Qfxw/view","access_verified":false}],"source":"Materialele de curs furnizate de administrator: obiectivul 4.2. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Autentificare și Windows Hello","url":"https://learn.microsoft.com/search/?terms=Windows%20Hello"}],"minutes":6},{"id":"4.3","chapter":4,"title":"Amenințări de securitate","subtitle":"Recunoaște mecanismul, nu doar numele.","sections":[{"title":"Malware: virus, worm, troian","text":"Virusul se atașează unui fișier/gazdă și se răspândește când este executat conținutul infectat. Worm-ul se poate replica și propaga între sisteme. Troianul se prezintă ca software legitim și poate executa acțiuni malițioase; nu este definit prin auto-replicare. Un singur malware poate combina mecanisme.","table":{"headers":["Tip","Idee-cheie"],"rows":[["Virus","Gazdă infectată"],["Worm","Auto-propagare"],["Troian","Deghizare"],["Logic bomb","Declanșare la condiție / moment"],["Ransomware","Blocare/criptare și adesea furt de date"],["Adware","Reclame și comportament nedorit"],["Spyware","Monitorizare și furt de informații"]]}},{"title":"DoS și DDoS","text":"Denial of Service urmărește indisponibilitatea serviciului prin epuizarea resurselor sau alte mecanisme. DDoS folosește surse distribuite. Un serviciu lent nu dovedește singur un atac; trebuie corelate simptomele și dovezile."},{"title":"Inginerie socială","text":"Atacatorul manipulează încrederea, urgența sau curiozitatea pentru a obține date ori acțiuni.","table":{"headers":["Tehnică","Indiciu"],"rows":[["Phishing","Mesaj/site fals care cere credențiale sau acțiuni"],["Smishing","Phishing prin SMS"],["Vishing","Prin voce / apel"],["Spoofing","Falsificarea identității sau originii"],["Clone phishing","Copie a unui mesaj legitim cu element malițios"],["Dumpster diving","Căutare de informații în materiale aruncate"]]}},{"title":"Amenințări fizice și observarea ecranului","text":"Un USB necunoscut poate conține malware, emula o tastatură (BadUSB) sau provoca daune electrice. Furtul expune dispozitivul și datele. Shoulder surfing înseamnă observarea directă a ecranului/tastării; screen scraping poate extrage conținut prin software, fără a fi neapărat o observație fizică."},{"title":"Reducerea riscului","text":"Actualizări, privilegii minime, MFA, blocarea ecranului, verificarea independentă a solicitărilor și backup-uri testate reduc impactul. BitLocker protejează datele de pe disc în condițiile sale de utilizare; Secure Boot verifică lanțul de pornire, nu certifică faptul că orice aplicație este sigură."}],"cards":[{"front":"Worm versus virus?","back":"Worm se auto-propagă; virusul folosește o gazdă infectată."},{"front":"Troian?","back":"Software deghizat ca legitim, cu funcție malițioasă."},{"front":"Smishing / vishing?","back":"Phishing prin SMS / prin voce."},{"front":"DDoS?","back":"Atac asupra disponibilității din surse distribuite."},{"front":"BadUSB?","back":"Dispozitiv USB cu comportament malițios, de exemplu emulare de tastatură."}],"quiz":[{"prompt":"Un mesaj SMS cere date bancare pe un site fals. Este:","options":["Defragmentare","Smishing","Hibernate"],"answer":1,"why":"Smishing este phishing prin SMS."},{"prompt":"Ce caracterizează un worm?","options":["Doar afișarea reclamelor","Auto-propagare","Lipsa totală a efectelor"],"answer":1,"why":"Auto-replicarea și răspândirea îl diferențiază de un troian simplu."},{"prompt":"Un atac din multe surse face un serviciu indisponibil. Este:","options":["DDoS","MFA","NTFS"],"answer":0,"why":"Distributed Denial of Service atacă disponibilitatea."},{"prompt":"Un stick găsit în parcare trebuie:","options":["Conectat pentru identificare","Formatat pe PC-ul personal","Predat conform procedurii, fără conectare"],"answer":2,"why":"Scanarea după conectare nu previne toate atacurile hardware."}],"warning":null,"videos":[],"source":"Materialele de curs furnizate de administrator: obiectivul 4.3. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Amenințări de securitate","url":"https://learn.microsoft.com/search/?terms=security%20threats"}],"minutes":6},{"id":"4.4","chapter":4,"title":"Răspuns la malware și phishing","subtitle":"Izolează, păstrează dovezile și verifică remedierea.","sections":[{"title":"Primii pași","text":"Dacă suspectezi malware activ, izolează dispozitivul de rețea conform procedurii organizației și contactează IT/securitatea. Notează ora, mesajele și acțiunile recente. Nu șterge în grabă jurnale sau fișiere care pot constitui dovezi și nu opri arbitrar sistemul dacă echipa de răspuns are nevoie de date volatile."},{"title":"Protecția Defender","text":"Windows Security → Virus & threat protection. Verifică protecția în timp real, actualizările de securitate și opțiunile cloud conform politicii. Controlled Folder Access limitează modificările neautorizate în foldere protejate, dar nu înlocuiește backup-ul. Aplicațiile legitime blocate se investighează înainte de creare de excepții.","image":"folder-access"},{"title":"Alege scanarea potrivită","text":"Actualizează inteligența de securitate printr-o metodă sigură și autorizată, ținând cont de izolarea incidentului.","table":{"headers":["Scanare","Scop"],"rows":[["Quick","Zone comune de persistență și amenințări active"],["Full","Verificare mai extinsă; domeniul depinde de setări și excluderi"],["Custom","Fișiere/foldere/unități selectate"],["Microsoft Defender Offline","Repornire și scanare în afara sesiunii Windows obișnuite"]]},"bullets":["Safe Mode este mod de diagnosticare, nu o garanție că malware-ul nu rulează. Defender poate să nu funcționeze acolo ca în modul normal.","Un rezultat fără detecții nu garantează singur că sistemul este complet curat."]},{"title":"Interpretează Protection history","text":"Verifică numele amenințării, locația, severitatea și starea acțiunii. Quarantine izolează elementul; Remove îl elimină; Allow on device permite un element și trebuie folosit numai după validarea unui fals pozitiv. Nu restaura un fișier doar fiindcă ai nevoie de el."},{"title":"Răspuns la phishing","text":"Dacă ai deschis doar pagina: închide-o, raportează și verifică descărcările sau permisiunile acordate; nu presupune automat infectarea. Dacă ai introdus credențiale: de pe un dispozitiv sigur schimbă parola pe serviciul legitim, revocă sesiunile, verifică metodele MFA și activitatea contului. Dacă ai executat un atașament suspect: tratează dispozitivul ca potențial compromis și escaladează.","bullets":["Pentru conturi financiare contactează instituția printr-un canal verificat.","Nu șterge mesajul și istoricul înainte de raportare dacă sunt necesare ca dovezi.","Schimbarea parolei singură poate fi insuficientă când au fost furate sesiuni/tokenuri."]},{"title":"USB necunoscut: nu îl conecta","text":"Nu există o procedură sigură pentru utilizator bazată doar pe dezactivarea AutoPlay și scanare. Acestea nu opresc BadUSB sau daunele electrice. Predă dispozitivul responsabililor; analiza se face numai în laborator specializat și autorizat.","image":"usb-risk"},{"title":"După incident","text":"Validează remedierea, actualizează sistemul și aplicațiile, verifică protecțiile și schimbă credențialele compromise de pe un dispozitiv sigur. Pentru incidente serioase poate fi necesară reinstalarea din sursă de încredere. Aplică 3-2-1: trei copii, două medii, una în altă locație; adaugă o copie offline/imutabilă și testează restaurarea."}],"cards":[{"front":"Prima idee la malware activ?","back":"Conținere/izolare și raportare conform procedurii."},{"front":"Safe Mode garantează eliminarea malware-ului?","back":"Nu. Este diagnostic; scanarea offline este alt mecanism."},{"front":"Quarantine versus Allow?","back":"Quarantine izolează; Allow permite și necesită validare strictă."},{"front":"Credențiale date unui site fals?","back":"Schimbare pe serviciul legitim de pe dispozitiv sigur, revocare sesiuni și raportare."},{"front":"USB găsit: scanare după conectare?","back":"Nu îl conecta. Predă-l pentru analiză autorizată."}],"quiz":[{"prompt":"Ai executat un atașament suspect pe PC-ul de serviciu. Ce faci?","options":["Ștergi jurnalele","Izolezi conform procedurii și raportezi","Trimiți fișierul colegilor"],"answer":1,"why":"Limitarea impactului și păstrarea dovezilor preced curățarea improvizată."},{"prompt":"Ce acțiune izolează un fișier detectat?","options":["Quarantine","Allow","Pin"],"answer":0,"why":"Carantina împiedică utilizarea normală a elementului suspect."},{"prompt":"AutoPlay dezactivat face sigur orice USB necunoscut?","options":["Nu","Da","Doar pe Windows 11"],"answer":0,"why":"BadUSB și atacurile electrice nu depind de AutoPlay."},{"prompt":"După furtul credențialelor verifici și:","options":["Doar wallpaper-ul","Doar spațiul liber","Sesiunile active și metodele MFA"],"answer":2,"why":"Tokenurile și sesiunile pot rămâne active după un incident."}],"warning":"Recomandarea din sursă de a conecta un USB necunoscut pentru scanare a fost înlocuită cu procedura sigură: nu îl conecta.","videos":[],"source":"Materialele de curs furnizate de administrator: obiectivul 4.4. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Răspuns la malware și phishing","url":"https://learn.microsoft.com/search/?terms=Microsoft%20Defender%20Offline"}],"minutes":7},{"id":"4.5","chapter":4,"title":"User Account Control (UAC)","subtitle":"Elevarea privilegiilor nu înseamnă protecție antivirus.","sections":[{"title":"Rolul UAC","text":"UAC controlează elevarea privilegiilor. În configurația obișnuită, chiar un administrator rulează majoritatea aplicațiilor cu un token filtrat și elevează sarcinile administrative când este necesar. UAC susține privilegiul minim, dar nu este antivirus și nici o garanție că nicio acțiune malițioasă nu poate avea loc."},{"title":"Consent versus Credential","text":"Administratorul primește de regulă confirmare Yes/No; utilizatorul standard trebuie să furnizeze credențiale administrative autorizate. Politicile pot cere parolă și administratorului sau pot refuza elevarea utilizatorului standard. „Run as administrator” cere explicit elevare.","image":"uac-prompt"},{"title":"Secure Desktop","text":"În mod implicit, solicitarea apare pe un desktop securizat, cu fundal estompat. Izolarea limitează interacțiunea proceselor de pe desktopul obișnuit cu solicitarea. Verifică aplicația, editorul, sursa și dacă ai inițiat acțiunea; o semnătură digitală nu garantează că programul este potrivit sau inofensiv."},{"title":"Cele patru trepte","text":"Caută „Change User Account Control settings”. Glisorul grupează politici de notificare, în special pentru administratorul în Admin Approval Mode; nu este o scală universală pentru orice cont sau politică.","table":{"headers":["Treaptă","Comportament uzual"],"rows":[["Always notify","Solicitări pentru aplicații și schimbări de setări Windows; Secure Desktop"],["Implicit","Solicitări la modificări de aplicații; Secure Desktop"],["Fără estompare","Solicitările apar fără Secure Desktop"],["Never notify","Reduce/elimină solicitările pentru administrator; nu echivalează cu dezactivarea completă a tuturor mecanismelor UAC"]]},"image":"uac-slider"},{"title":"Configurare responsabilă","text":"Păstrează nivelul implicit sau politica organizației. Pentru operațiuni administrative folosește aplicația necesară, pe durata necesară; nu dezactiva UAC ca remediu de rutină. EnableLUA este o setare distinctă de glisor, iar schimbarea politicilor avansate poate necesita repornire și poate afecta aplicațiile. Virtualizarea UAC ajută anumite aplicații legacy, nu orice aplicație modernă."}],"cards":[{"front":"UAC ce controlează?","back":"Elevarea privilegiilor pentru sarcini administrative."},{"front":"Administrator versus standard la solicitare?","back":"De obicei consimțământ versus credențiale; politicile pot schimba comportamentul."},{"front":"Fără estompare = doar cosmetic?","back":"Nu. Solicitarea nu mai folosește Secure Desktop."},{"front":"Never notify dezactivează complet UAC?","back":"Nu. Nu este echivalent cu toate setările avansate, inclusiv EnableLUA."}],"quiz":[{"prompt":"Un utilizator standard trebuie să instaleze software autorizat pentru toți utilizatorii. Ce apare de regulă?","options":["Credential Prompt","Doar schimbarea temei","Nicio verificare posibilă"],"answer":0,"why":"Elevarea poate cere credențiale de administrator."},{"prompt":"Ce protejează interacțiunea cu solicitarea UAC?","options":["Secure Desktop","FAT32","SSID"],"answer":0,"why":"Desktopul securizat izolează solicitarea de desktopul obișnuit."},{"prompt":"Un editor verificat în UAC înseamnă că aprobi automat?","options":["Da","Numai dacă numele e lung","Nu"],"answer":2,"why":"Verifică și necesitatea, sursa și acțiunea inițiată."},{"prompt":"Care practică este preferabilă?","options":["UAC permanent dezactivat","Nivel implicit / politică și elevare numai când trebuie","Orice aplicație rulează elevat"],"answer":1,"why":"Privilegiul minim limitează riscul."}],"warning":null,"videos":[],"source":"Materialele de curs furnizate de administrator: obiectivul 4.5. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: User Account Control (UAC)","url":"https://learn.microsoft.com/search/?terms=User%20Account%20Control"}],"minutes":6},{"id":"5.1","chapter":5,"title":"Metoda de depanare","subtitle":"Observă, colectează dovezi, testează și escaladează.","sections":[{"title":"Un flux repetabil","text":"1. Definește simptomul și impactul. 2. Întreabă ce s-a schimbat și încearcă reproducerea sigură. 3. Colectează date. 4. Formulează și testează o ipoteză, cu o schimbare controlată odată. 5. Verifică funcționarea și documentează soluția. Cere backup/aprobare înainte de operațiuni invazive."},{"title":"Event Viewer","text":"eventvwr.msc deschide jurnalele. Windows Logs include Application, Security și System. Filtrează intervalul, nivelul și sursa; corelează ora incidentului și Event ID cu contextul. Un eveniment Error nu dovedește singur cauza problemei.","code":"eventvwr.msc","bullets":["Application: evenimente ale aplicațiilor. System: componente și servicii ale sistemului. Security: evenimente auditate.","Salvează evenimentele relevante în .evtx pentru escaladare; nu șterge jurnalele ca „reparație”."],"image":"events"},{"title":"Task Manager versus jurnale","text":"Ctrl + Shift + Esc arată procesele și consumul actual de CPU, RAM, disc și rețea. Event Viewer oferă istoric. Sortează consumul și corelează cu simptomul; activitatea intensă poate fi legitimă. End task poate pierde date nesalvate, deci încearcă mai întâi închiderea normală."},{"title":"Optimize Drives","text":"HDD poate beneficia de defragmentare. SSD este gestionat de Windows prin optimizări potrivite, inclusiv TRIM; nu forța repetat defragmentarea cu utilitare vechi. Lasă sistemul să aleagă operația potrivită tipului de mediu. Un disc suspect de defectare se protejează prin backup și diagnostic, nu prin optimizare agresivă."},{"title":"Colectarea datelor","text":"Notează mesajul exact, pașii de reproducere, ora, versiunea OS și schimbările recente. msinfo32 oferă informații de sistem: Save produce .nfo, iar Export produce text. Capturile și rapoartele pot conține date personale sau secrete: redactează-le înainte de partajare.","code":"msinfo32\ngpupdate /force\ngpresult /r","bullets":["Caută întâi în documentația Microsoft sau a producătorului, cu mesajul exact și versiunea.","gpupdate /force reaplică politici; gpresult arată rezultatul. O politică poate explica o opțiune blocată."]},{"title":"Când escaladezi?","text":"Escaladează când există risc pentru date, securitate, hardware, servicii critice sau când operația depășește permisiunile tale. Include impactul, dovezile, pașii încercați și rezultatul lor. Nu continua încercări distructive doar ca să eviți escaladarea."}],"cards":[{"front":"Event Viewer versus Task Manager?","back":"Istoric de evenimente versus activitate și procese curente."},{"front":"msinfo32 Save versus Export?","back":"Save: .nfo. Export: text."},{"front":"gpupdate versus gpresult?","back":"Reaplică politici versus arată rezultatul aplicării."},{"front":"Când escaladezi?","back":"La risc pentru date/securitate, impact mare, lipsă de permisiuni sau diagnostic peste competență."}],"quiz":[{"prompt":"Vrei să vezi ce s-a întâmplat la ora unei erori. Deschizi:","options":["Paint","Taskbar settings","Event Viewer"],"answer":2,"why":"Jurnalele permit corelarea evenimentelor în timp."},{"prompt":"Cum salvezi un raport text din msinfo32?","options":["Save ca .nfo","Format","Export"],"answer":2,"why":"Export generează text; Save produce raportul .nfo."},{"prompt":"Ce faci dacă o politică blochează o setare?","options":["Ocolești politica","Investighezi gpresult și contactezi administratorul","Ștergi registrul"],"answer":1,"why":"Politicile administrate trebuie investigate și modificate prin canal autorizat."},{"prompt":"Care este o ipoteză bună de testat?","options":["O cauză specifică, cu schimbare controlată și verificare","Zece modificări simultan","Orice recomandare anonimă"],"answer":0,"why":"Schimbările izolate permit atribuirea rezultatului."}],"warning":null,"videos":[],"source":"Materialele de curs furnizate de administrator: obiectivul 5.1. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Metoda de depanare","url":"https://learn.microsoft.com/search/?terms=Windows%20troubleshooting"}],"minutes":6},{"id":"5.2","chapter":5,"title":"Depanarea Windows și a aplicațiilor","subtitle":"Începe cu soluțiile reversibile, apoi recuperare.","sections":[{"title":"Reparare înainte de resetare","text":"Identifică dacă problema ține de aplicație, profil, driver sau sistem. Verifică actualizările, mesajul de eroare și schimbările recente. Înainte de resetare/reinstalare salvează datele, licențele și cheia de recuperare BitLocker; verifică backup-ul și autorizarea."},{"title":"Reset this PC și Go back","text":"Keep my files reinstalează Windows păstrând fișierele personale vizate, dar elimină aplicații și resetează setări; nu înlocuiește backup-ul. Remove everything elimină datele, aplicațiile și setările conform opțiunilor alese. Local reinstall folosește fișiere locale; Cloud download descarcă fișiere Windows și necesită internet.","table":{"headers":["Opțiune","Când","Limită"],"rows":[["Keep my files","Reinstalare cu păstrarea fișierelor personale","Aplicațiile trebuie reinstalate"],["Remove everything","Reinstalare cu eliminarea datelor","Verifică unitățile și metoda de ștergere"],["Go back","Revenire după upgrade","Fereastră limitată, de regulă 10 zile, și fișierele necesare intacte"]]},"bullets":["Curățarea de consum din Reset nu este o garanție de sanitizare conform standardelor enterprise.","Cloud download nu este un upgrade automat la orice ediție și nu ocolește toate problemele hardware."]},{"title":"WinRE și instrumentele de recuperare","text":"Intră prin Shift + Restart sau Settings → Recovery → Advanced startup. WinRE poate fi disponibil și de pe mediul de instalare prin Repair your computer. Startup Repair încearcă repararea pornirii; System Restore folosește puncte de restaurare și nu este backup al fișierelor personale. Reset this PC se află de regulă sub Troubleshoot, nu în orice ecran Advanced options.","image":"recovery"},{"title":"Safe Mode: 4, 5, 6","text":"Troubleshoot → Advanced options → Startup Settings → Restart. F4 pornește cu set minim; F5 adaugă suport de rețea unde este disponibil; F6 folosește Command Prompt în locul interfeței obișnuite și nu include implicit driverele de rețea.","bullets":["Dacă problema dispare, investighează diferențele de drivere/servicii; nu ai încă dovada definitivă a cauzei.","Repornește normal pentru ieșire; dacă Safe boot a fost setat în msconfig, trebuie debifat autorizat.","Nu confunda Safe Mode cu Microsoft Defender Offline."],"image":"safe-mode"},{"title":"Compatibilitate, Repair și Reset","text":"Pentru aplicații legacy, Properties → Compatibility poate oferi setări compatibile; funcțiile de depanare automată diferă după versiune. Modurile de compatibilitate nu convertesc arhitectura și nu fac sigur un program necunoscut. Rulează ca administrator numai dacă este justificat, nu ca setare universală.","image":"compatibility"},{"title":"Microsoft Store și aplicații desktop","text":"Verifică internetul, data/ora, spațiul și actualizările. wsreset.exe golește cache-ul Store. Settings → Apps oferă Repair sau Reset dacă aplicația permite; pentru Win32, Programs and Features → Change/Repair. Salvează datele aplicației înainte de resetare ori dezinstalare.","code":"wsreset.exe"},{"title":"S mode, servicii și startup","text":"S mode restricționează software-ul și anumite opțiuni; nu elimină complet malware-ul. Escaladarea nu înseamnă ieșire automată din S mode: verifică necesitatea și aprobarea, deoarece comutarea normală este unidirecțională. services.msc permite verificarea stării, tipului de pornire și dependențelor. Nu opri servicii critice la întâmplare.","bullets":["Task Manager → Startup apps → Disable împiedică pornirea automată; nu dezinstalează aplicația.","Task Manager → End task poate pierde date. Services permite anumite operații, în funcție de permisiuni.","Dacă services.msc nu se deschide, investighează eroarea; nu presupune automat corupere de sistem."],"image":"services"}],"cards":[{"front":"Keep my files păstrează aplicațiile instalate?","back":"În general nu. Păstrează fișierele personale vizate, dar elimină aplicații și resetează setări."},{"front":"F4 / F5 / F6?","back":"Safe Mode / cu rețea / cu Command Prompt, fără rețea implicită."},{"front":"Startup Disable dezinstalează?","back":"Nu. Oprește lansarea automată."},{"front":"System Restore este backup de documente?","back":"Nu. Revine asupra componentelor/configurației sistemului."},{"front":"Escaladare S mode = ieșire imediată?","back":"Nu. Trebuie analizată și aprobată schimbarea."}],"quiz":[{"prompt":"Ce variantă Safe Mode adaugă suportul de rețea?","options":["F4","F6 implicit","F5"],"answer":2,"why":"F5 este Safe Mode with Networking; disponibilitatea adaptorului poate varia."},{"prompt":"Ce verifici înainte de Reset this PC?","options":["Doar fundalul","Backup și cheie BitLocker, dacă se aplică","Nimic"],"answer":1,"why":"Recuperarea poate pierde date și poate necesita cheia de recuperare."},{"prompt":"Disable la Startup apps:","options":["Nu dezinstalează aplicația","Șterge toate fișierele","Formatează discul"],"answer":0,"why":"Schimbă comportamentul de pornire automată."},{"prompt":"Ce instrument poate ajuta la repararea boot-ului?","options":["ClearType","Pin to Start","Startup Repair"],"answer":2,"why":"Startup Repair vizează probleme comune de pornire."}],"warning":null,"videos":[],"source":"Materialele de curs furnizate de administrator: obiectivul 5.2. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Depanarea Windows și a aplicațiilor","url":"https://learn.microsoft.com/search/?terms=Windows%20recovery"}],"minutes":8},{"id":"5.3","chapter":5,"title":"Hardware și periferice: diagnostic","subtitle":"De la alimentare și cablu la driver și dispozitiv.","sections":[{"title":"Mai întâi verificări simple","text":"Verifică alimentarea, comutatorul, cablul, portul și conexiunea fizică. Testează un cablu sau port cunoscut ca bun și, dacă este sigur și autorizat, alt dispozitiv. Schimbă câte un element odată. Nu deschide surse de alimentare și nu interveni intern fără pregătire și protecție adecvată."},{"title":"Device Manager și drivere","text":"devmgmt.msc arată dispozitivele și starea lor. Semnul galben indică o problemă; săgeata în jos poate indica un dispozitiv dezactivat. Properties → General oferă codul de eroare; Driver oferă Update, Roll Back, Disable și Uninstall, după caz.","code":"devmgmt.msc\ndiskmgmt.msc","image":"device-manager"},{"title":"Actualizare versus rollback","text":"Actualizează din surse oficiale când driverul lipsește, are erori sau producătorul recomandă. Dacă problema a început imediat după update, Roll Back Driver poate reveni la versiunea disponibilă anterior. Dacă butonul nu este disponibil, investighează opțiunile producătorului și păstrează un driver cunoscut ca bun înainte de dezinstalare.","image":"rollback"},{"title":"Coduri uzuale: indicii, nu verdict","text":"Codul de eroare ajută la formularea ipotezei, nu dovedește singur cauza.","table":{"headers":["Cod","Idee principală"],"rows":[["10","Dispozitivul nu poate porni"],["12","Resurse insuficiente / conflict"],["19","Informații de configurare în registru cu probleme"],["22","Dispozitiv dezactivat"],["28","Drivere neinstalate"],["43","Dispozitivul a raportat o problemă și Windows l-a oprit"],["45","Dispozitivul nu este conectat în prezent"]]}},{"title":"Intrare, imagine, sunet și cameră","text":"Tastatură: verifică layout-ul și opțiunile de accesibilitate. Mouse: baterie, receptor, port și setări. Monitor: intrare, cablu, Win + P și rezoluție. Sunet: ieșirea aleasă, volum/mute, aplicație și driver. Microfon/cameră: dispozitivul selectat, permisiunile de confidențialitate și utilizarea de către altă aplicație."},{"title":"Stocare și rețea","text":"Disk Management arată discuri, partiții și litere; Device Manager arată hardware și drivere. Un volum sănătos fără literă poate necesita atribuirea ei. Un disc RAW sau neinițializat poate conține date: oprește scrierile și pregătește recuperarea. Pentru NAS verifică rețeaua, SMB, autentificarea și permisiunile; nu activa SMB1 ca remediu automat."},{"title":"Imprimante, scanere și Bluetooth","text":"Imprimantă: alimentare, hârtie/cerneală, conexiune, coadă și dispozitiv implicit. O coadă blocată poate necesita gestionarea joburilor sau repornirea autorizată a Print Spooler. Scanner: aplicație, driver WIA/TWAIN și conectivitate. Bluetooth: dispozitiv în pairing, baterie, rază, profil compatibil și eventual reîmperechere."}],"cards":[{"front":"Cod 28?","back":"Driverele nu sunt instalate."},{"front":"Cod 43 dovedește defect fizic?","back":"Nu. Dispozitivul a raportat o problemă; cauza trebuie investigată."},{"front":"Disk Management versus Device Manager?","back":"Volume/partiții versus hardware/drivere."},{"front":"Cameră fără imagine: ce verifici?","back":"Conexiune, dispozitiv selectat, permisiuni de confidențialitate, altă aplicație și driver."},{"front":"Rollback când?","back":"Când problema apare după actualizarea driverului și există o versiune anterioară disponibilă."}],"quiz":[{"prompt":"O problemă începe imediat după actualizarea driverului. Ce opțiune investighezi?","options":["Format imediat","Roll Back Driver","Allow on device"],"answer":1,"why":"Revenirea poate anula schimbarea asociată apariției problemei."},{"prompt":"Codul 22 indică de regulă:","options":["RAM plină","Fișier criptat","Dispozitiv dezactivat"],"answer":2,"why":"Verifică dacă activarea este autorizată și potrivită."},{"prompt":"Un disc important apare RAW. Ce e greșit să faci imediat?","options":["Să protejezi datele","Să îl formatezi","Să soliciți recuperare"],"answer":1,"why":"Formatarea scrie pe disc și poate compromite recuperarea."},{"prompt":"Microfonul merge într-o aplicație, dar nu în alta. Ce verifici?","options":["Selecția și permisiunile aplicației","Numai cablul de alimentare","Stilul GPT"],"answer":0,"why":"Contextul aplicației poate explica problema fără defect hardware."}],"warning":null,"videos":[],"source":"Materialele de curs furnizate de administrator: obiectivul 5.3. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Hardware și periferice: diagnostic","url":"https://learn.microsoft.com/search/?terms=Device%20Manager%20error%20codes"}],"minutes":6},{"id":"5.4","chapter":5,"title":"Rețele și domenii: diagnostic","subtitle":"Verifică legătura, configurația IP, numele și autorizarea.","sections":[{"title":"Ethernet și Wi-Fi","text":"Ethernet: verifică alimentarea echipamentelor, cablul, portul și LED-urile de link/activitate; un link activ nu garantează acces la internet. Wi-Fi: confirmă SSID-ul corect, parola/metoda de autentificare și puterea semnalului. SSID-ul nu este dovadă că rețeaua este legitimă.","code":"netsh wlan show interfaces","bullets":["Semnalul procentual este orientativ și depinde de adaptor; nu măsoară direct viteza sau congestia.","În rețele enterprise autentificarea poate folosi identitate/certificat, nu doar o parolă comună.","Nu reporni echipamente comune ale organizației fără aprobare."],"image":"ethernet"},{"title":"ipconfig: ce vezi și ce modifici","text":"Începe cu configurația existentă, nu cu resetări.","table":{"headers":["Comandă","Rol"],"rows":[["ipconfig /all","Afișează IP, mască, gateway, DNS, DHCP și alte detalii"],["ipconfig /release","Eliberează configurația DHCP a adaptorului vizat"],["ipconfig /renew","Cere/reînnoiește configurația DHCP; nu garantează alt IP"],["ipconfig /flushdns","Golește cache-ul local al resolverului DNS"]]},"bullets":["/release și /renew vizează DHCP, nu repară o configurație statică. Pot întrerupe o sesiune remote.","169.254.x.x poate indica auto-configurare IPv4 link-local când nu se obține DHCP.","flushdns nu schimbă serverele DNS și nu repară orice problemă de conectivitate."],"image":"ipconfig"},{"title":"ping: test limitat, nu verdict complet","text":"ping trimite ICMP Echo și măsoară timpul dus-întors. Testează progresiv loopback, gateway, o destinație autorizată și un nume. Un răspuns confirmă acel tip de comunicare; un timeout poate însemna și ICMP filtrat. Latența nu este lățimea de bandă.","code":"ping 127.0.0.1\nping <gateway-ul-tău>\nping prep-certificat.vercel.app","bullets":["Dacă numele se rezolvă, dar ping nu răspunde, DNS poate funcționa chiar dacă ICMP este blocat.","„Destination host unreachable” poate veni și de la dispozitivul local, nu numai de la un router."]},{"title":"tracert: exemplul Prep","text":"În Windows, tracert încearcă să arate hop-urile către destinație. Mai jos este comanda cerută pentru site-ul Prep, nu rezultatul unei măsurători. Rutele, adresele și timpii se schimbă după locație și moment.","code":"tracert prep-certificat.vercel.app","bullets":["* * * înseamnă lipsa răspunsului la probele acelui hop; nu dovedește singur întreruperea conexiunii.","O latență mare pe un singur hop, cu hop-uri ulterioare normale, nu dovedește congestie acolo.","Corelează cu destinația finală și teste suplimentare; nu promite localizarea exactă a oricărei defecțiuni."]},{"title":"Nmap: numai pe ținte autorizate","text":"Nmap inventariază host-uri și porturi. Pe Windows poate necesita Npcap pentru anumite probe. Descărcarea se face de la proiectul oficial. Restrânge testele la laborator sau la sisteme pentru care ai permisiune explicită; rezultatele depind de probe, acces și filtrare.","code":"nmap --version\nnmap -sn <subrețea-autorizată/CIDR>\nnmap -p 80,443 <gazdă-autorizată>\nnmap -sV <gazdă-autorizată>","table":{"headers":["Stare","Interpretare"],"rows":[["open","Un serviciu acceptă comunicații pe port"],["closed","Port accesibil, fără serviciu ascultând la probă"],["filtered","Probele nu permit stabilirea stării; filtrarea este o posibilă explicație, nu o dovadă completă"]]}},{"title":"Alăturarea la AD DS","text":"Verifică ediția Windows acceptată, conectivitatea la DC, DNS-ul domeniului și sincronizarea timpului. Sunt necesare drepturi locale și un cont autorizat să adauge computerul; nu este obligatoriu să fie Domain Admin dacă sarcina este delegată. Windows Home nu se alătură unui domeniu AD DS prin funcția încorporată.","bullets":["sysdm.cpl → Computer Name → Change oferă metoda clasică de domain/workgroup.","AD DS domain join diferă de Microsoft Entra join sau simpla adăugare a unui cont de serviciu.","Repornește la solicitare și verifică autentificarea cu identitatea potrivită."]},{"title":"Scoaterea din domeniu","text":"Înainte de unjoin: aprobarea IT, backup și chei de recuperare, un cont administrativ local testat și un plan pentru date/aplicații. Mutarea în workgroup schimbă relația de domeniu și necesită de regulă repornire. Datele vechiului profil nu dispar automat, dar accesul și migrarea trebuie pregătite.","bullets":["Nu presupune că toate setările GPO sunt anulate automat; unele persistă.","Certificatele, datele criptate, accesul la resurse și aplicațiile organizației pot fi afectate.","Resetarea rețelei este ultimă opțiune: poate necesita refacerea VPN, adaptoarelor și setărilor IP."]}],"cards":[{"front":"ipconfig /all?","back":"Arată configurația detaliată; nu o resetează."},{"front":"flushdns?","back":"Golește cache-ul DNS local, nu schimbă serverul DNS."},{"front":"Ping timeout = server oprit?","back":"Nu neapărat. ICMP poate fi filtrat."},{"front":"Comanda tracert a lecției?","back":"tracert prep-certificat.vercel.app"},{"front":"Înainte de unjoin?","back":"Aprobare, backup, chei de recuperare și administrator local testat."}],"quiz":[{"prompt":"Ce comandă afișează DNS, gateway și DHCP?","options":["ipconfig /flushdns","format","ipconfig /all"],"answer":2,"why":"/all afișează configurația detaliată."},{"prompt":"Un hop tracert arată * * *, dar următoarele răspund. Ce concluzionezi?","options":["Hop-ul nu răspunde probelor; nu este dovadă suficientă de defect","Rețeaua este sigur întreruptă","Trebuie formatat PC-ul"],"answer":0,"why":"Unele routere nu răspund la probe sau le limitează."},{"prompt":"Ce pregătești înainte de scoaterea din domeniu?","options":["Doar alt wallpaper","O parolă inventată","Cont local administrativ testat și backup"],"answer":2,"why":"Fără acces local pregătit poți pierde accesul la sistem și date."},{"prompt":"Când folosești Nmap?","options":["Pe orice rețea fără acord","Numai pe ținte autorizate","Ca să schimbi automat DNS"],"answer":1,"why":"Scanarea trebuie să respecte autorizarea și scopul convenit."}],"warning":null,"videos":[],"source":"Materialele de curs furnizate de administrator: obiectivul 5.4. Explicații reformulate și corecturi editoriale Prep.","references":[{"title":"Documentație Microsoft: Rețele și domenii: diagnostic","url":"https://learn.microsoft.com/search/?terms=Windows%20ipconfig%20tracert"}],"minutes":8}],"sourceNote":"Adaptare educațională a materialelor furnizate. Imaginile originale pot reflecta versiuni vechi; explicațiile revizuite indică limitele și diferențele. Mini-testele sunt exerciții Prep, nu întrebări oficiale de examen."};
